CREATE OR REPLACE FUNCTION public.complete_current_tutorial_formation()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid:=auth.uid(); v_step text; v_party text[]; v_guaranteed_master text; v_leader_owned uuid; v_leader_level integer;
  v_skill uuid; v_skill_master text; v_skill_name text; v_starter_granted boolean:=false; v_save jsonb; v_defense jsonb; v_grant jsonb;
begin
  if v_user_id is null then raise exception 'authentication required' using errcode='42501'; end if;
  select step_id into v_step from public.tutorial_progress where user_id=v_user_id for update;
  if v_step in ('DISPATCH','FREE_INSTANT','TUTORIAL_BATTLE','RULE_GUIDE','COMPLETE','AUTHENTICATION') then
    return jsonb_build_object('status','already_advanced','tutorial_step',v_step);
  end if;
  if v_step<>'AUTO_FORMATION' then raise exception 'tutorial formation is unavailable'; end if;
  if not exists(select 1 from public.user_funnel_milestones where user_id=v_user_id and milestone='first_growth') then
    raise exception 'character growth is required before formation' using errcode='23514';
  end if;
  select canonical_payload into v_grant from public.user_lifetime_onboarding_grants where user_id=v_user_id;
  if v_grant is not null then
    v_guaranteed_master:=v_grant->>'guaranteed_ssr';
  else
    select result->>'character_id' into v_guaranteed_master
    from public.gacha_execution_history history
    cross join lateral jsonb_array_elements(coalesce(history.result_payload->'results','[]'::jsonb)) result
    where history.user_id=v_user_id and history.status='COMPLETED'
      and coalesce((history.result_payload->>'tutorial')::boolean,false)
      and coalesce((result->>'tutorial_slot')::integer,0)=10
    order by history.created_at desc limit 1;
  end if;
  if v_guaranteed_master is null then raise exception 'guaranteed tutorial gacha result is required' using errcode='23514'; end if;
  select owned.id,owned.level into v_leader_owned,v_leader_level from public.user_characters owned
    where owned.user_id=v_user_id and owned.character_id=v_guaranteed_master limit 1;
  if v_leader_owned is null then raise exception 'guaranteed tutorial character is not owned' using errcode='23514'; end if;
  if coalesce(v_leader_level,0)<7 then raise exception 'tutorial Character must reach level 7 before formation' using errcode='23514'; end if;

  if v_grant is not null then
    select array_agg(value order by ordinality) into v_party
    from jsonb_array_elements_text(v_grant->'formation_character_ids') with ordinality selected(value,ordinality);
    if cardinality(v_party)<>5 or (select count(*) from public.user_characters where user_id=v_user_id and character_id=any(v_party))<>5 then
      raise exception 'lifetime tutorial formation cannot be restored' using errcode='23514';
    end if;
    if v_party[1] is distinct from v_grant->>'leader_character' then
      raise exception 'lifetime tutorial leader is invalid' using errcode='23514';
    end if;
  else
    select array_agg(character_id order by is_guaranteed desc,is_ssr desc,created_at desc) into v_party from (
      select owned.character_id,owned.created_at,(owned.id=v_leader_owned) is_guaranteed,(master.rarity='SSR') is_ssr
      from public.user_characters owned join public.canonical_character_master master
        on master.version='2026-08-21' and master.character_id=owned.character_id
      where owned.user_id=v_user_id
      order by (owned.id=v_leader_owned) desc,(master.rarity='SSR') desc,owned.created_at desc limit 5
    ) picked;
  end if;
  if coalesce(cardinality(v_party),0)=0 then raise exception 'owned character required'; end if;
  v_save:=public.save_main_formation(v_party);
  v_defense:=public.save_pvp_defense_deck(v_party,'ATTACK_PRIORITY');

  if v_grant is not null then
    v_skill_master:=v_grant->>'starter_skill';
    select display_name into v_skill_name from public.skill_battle_master where skill_id=v_skill_master and enabled;
    if v_skill_name is null then raise exception 'lifetime tutorial starter skill is unavailable' using errcode='P0002'; end if;
    select id into v_skill from public.user_skills where user_id=v_user_id and skill_card_id=v_skill_master order by created_at,id limit 1;
    if v_skill is null then
      insert into public.user_skills(user_id,skill_card_id,plus_val) values(v_user_id,v_skill_master,0) returning id into v_skill;
      v_starter_granted:=true;
    end if;
  else
    select skill.id,master.skill_id,master.display_name into v_skill,v_skill_master,v_skill_name
    from public.user_skills skill join public.skill_battle_master master on master.skill_id=skill.skill_card_id and master.enabled
    where skill.user_id=v_user_id and (master.exclusive_character_id is null or master.exclusive_character_id=v_party[1])
    order by coalesce(master.power_percent,0) desc,skill.created_at asc limit 1;
    if v_skill is null then
      select master.skill_id,master.display_name into v_skill_master,v_skill_name
      from public.skill_battle_master master where master.skill_id='SKILL_001' and master.enabled and master.exclusive_character_id is null;
      if v_skill_master is null then raise exception 'tutorial starter skill is unavailable' using errcode='P0002'; end if;
      select id into v_skill from public.user_skills where user_id=v_user_id and skill_card_id=v_skill_master order by created_at,id limit 1;
      if v_skill is null then
        insert into public.user_skills(user_id,skill_card_id,plus_val) values(v_user_id,v_skill_master,0) returning id into v_skill;
        v_starter_granted:=true;
      end if;
    end if;
  end if;
  select id into v_leader_owned from public.user_characters where user_id=v_user_id and character_id=v_party[1] limit 1;
  perform public.set_character_skill(v_leader_owned,v_skill,0);
  update public.users set favorite_character_id=v_party[1] where id=v_user_id;
  update public.tutorial_progress set step_id='DISPATCH',updated_at=now() where user_id=v_user_id and step_id='AUTO_FORMATION';
  return jsonb_build_object('status','advanced','tutorial_step','DISPATCH','formation',v_save,'defense',v_defense,
    'leader_character_id',v_party[1],'leader_user_character_id',v_leader_owned,'leader_level',v_leader_level,
    'skill_equipped',true,'skill_id',v_skill_master,'skill_name',v_skill_name,'starter_skill_granted',v_starter_granted,
    'lifetime_replay',v_grant is not null);
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_gvg_match_on_timeout(p_match_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_match public.gvg_match_sessions%ROWTYPE; v_a NUMERIC; v_b NUMERIC; v_winner UUID; v_reason TEXT;
BEGIN
  SELECT * INTO v_match FROM public.gvg_match_sessions WHERE id = p_match_session_id FOR UPDATE;
  IF NOT FOUND OR v_match.status <> 'ACTIVE' THEN RAISE EXCEPTION 'GvG match is not active'; END IF;
  IF now() < v_match.scheduled_end_at THEN RAISE EXCEPTION 'GvG match has not ended'; END IF;
  v_a := v_match.guild_a_collapses + ((v_match.guild_a_phase_max_hp - v_match.guild_a_phase_hp)::NUMERIC / v_match.guild_a_phase_max_hp);
  v_b := v_match.guild_b_collapses + ((v_match.guild_b_phase_max_hp - v_match.guild_b_phase_hp)::NUMERIC / v_match.guild_b_phase_max_hp);
  IF v_a > v_b THEN v_winner := v_match.guild_b_id; v_reason := 'TIMEOUT_PROGRESS';
  ELSIF v_b > v_a THEN v_winner := v_match.guild_a_id; v_reason := 'TIMEOUT_PROGRESS';
  ELSIF v_match.guild_a_last_progress_at IS NOT NULL AND (v_match.guild_b_last_progress_at IS NULL OR v_match.guild_a_last_progress_at < v_match.guild_b_last_progress_at) THEN v_winner := v_match.guild_b_id; v_reason := 'TIMEOUT_TIMESTAMP';
  ELSIF v_match.guild_b_last_progress_at IS NOT NULL AND (v_match.guild_a_last_progress_at IS NULL OR v_match.guild_b_last_progress_at < v_match.guild_a_last_progress_at) THEN v_winner := v_match.guild_a_id; v_reason := 'TIMEOUT_TIMESTAMP';
  ELSE v_winner := NULL; v_reason := 'DRAW'; END IF;
  UPDATE public.gvg_match_sessions SET status = 'COMPLETED', completed_at = now(), winner_guild_id = v_winner, result_reason = v_reason WHERE id = v_match.id;
  RETURN jsonb_build_object('winner_guild_id', v_winner, 'reason', v_reason, 'guild_a_progress', v_a, 'guild_b_progress', v_b);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_patrol_instant(p_user_id uuid, p_patrol_id uuid, p_diamond_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_diamonds INTEGER;
    v_patrol_exists BOOLEAN;
BEGIN
    SELECT diamonds INTO v_diamonds FROM public.users WHERE id = p_user_id;
    IF v_diamonds IS NULL OR v_diamonds < p_diamond_cost THEN
        RETURN jsonb_build_object('error', 'ダイヤが不足しています。');
    END IF;

    SELECT EXISTS(SELECT 1 FROM public.user_patrols WHERE id = p_patrol_id AND user_id = p_user_id) INTO v_patrol_exists;
    IF NOT v_patrol_exists THEN
        RETURN jsonb_build_object('error', 'クエストが存在しません。');
    END IF;

    UPDATE public.users SET diamonds = diamonds - p_diamond_cost WHERE id = p_user_id;
    DELETE FROM public.user_patrols WHERE id = p_patrol_id;

    RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_patrol_instantly(p_user_id uuid, p_patrol_id uuid, p_use_currency text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_currency text:=upper(coalesce(p_use_currency,'')); v_status text; v_free integer; v_paid integer; v_reset date; v_today date:=(now() at time zone 'Asia/Tokyo')::date; v_step text;
begin
 if v_uid is null or v_uid<>p_user_id then raise exception 'not authorized' using errcode='42501'; end if;
 select status into v_status from public.user_patrols where id=p_patrol_id and user_id=v_uid for update;
 if v_status is null then raise exception 'patrol not found' using errcode='P0002'; end if;
 if v_status<>'ONGOING' then raise exception 'patrol is not eligible for instant completion' using errcode='23514'; end if;
 if v_currency='FREE_TUTORIAL' then
  select step_id into v_step from public.tutorial_progress where user_id=v_uid for update;
  if v_step<>'FREE_INSTANT' then raise exception 'tutorial free instant completion is unavailable' using errcode='55000'; end if;
  update public.tutorial_progress set step_id='TUTORIAL_BATTLE',updated_at=now() where user_id=v_uid and step_id='FREE_INSTANT';
 elsif v_currency in ('FREE_PREOPEN','FREE') then
  select quest_free_skips_count,quest_paid_skips_count,quest_skips_reset_date into v_free,v_paid,v_reset from public.users where id=v_uid for update;
  if v_reset is distinct from v_today then v_free:=0; v_paid:=0; end if;
  if v_free>=5 then raise exception 'daily free instant completion limit reached' using errcode='23514'; end if;
  update public.users set quest_free_skips_count=v_free+1,quest_paid_skips_count=v_paid,quest_skips_reset_date=v_today where id=v_uid;
 elsif v_currency='DIAMOND' then
  select quest_free_skips_count,quest_paid_skips_count,quest_skips_reset_date into v_free,v_paid,v_reset from public.users where id=v_uid for update;
  if v_reset is distinct from v_today then v_free:=0; v_paid:=0; end if;
  if v_paid>=10 then raise exception 'daily paid instant completion limit reached' using errcode='23514'; end if;
  if (select neon_diamonds from public.users where id=v_uid)<30 then raise exception 'diamond insufficient' using errcode='23514'; end if;
  update public.users set neon_diamonds=neon_diamonds-30,quest_free_skips_count=v_free,quest_paid_skips_count=v_paid+1,quest_skips_reset_date=v_today where id=v_uid;
 else raise exception 'invalid patrol instant completion currency' using errcode='22023'; end if;
 update public.user_patrols set status='CLAIMABLE',expires_at=now() where id=p_patrol_id and user_id=v_uid;
 return jsonb_build_object('status','success','patrol_id',p_patrol_id,'currency',v_currency,'diamond_cost',case when v_currency='DIAMOND' then 30 else 0 end,'free_skips_remaining',case when v_currency in ('FREE_PREOPEN','FREE') then 4-v_free else null end,'paid_skips_remaining',case when v_currency='DIAMOND' then 9-v_paid else null end,'tutorial_step',case when v_currency='FREE_TUTORIAL' then 'TUTORIAL_BATTLE' else null end);
end $function$

CREATE OR REPLACE FUNCTION public.complete_patrol_preopen(p_patrol_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user uuid:=auth.uid(); v_level integer; v_status text;
begin
  if v_user is null then raise exception 'authentication required' using errcode='42501'; end if;
  if not exists(select 1 from public.feature_operating_states where feature_key='PRE_OPEN' and state='OPEN') then
    raise exception 'pre-open speed-up is closed';
  end if;
  select level into v_level from public.users where id=v_user;
  if coalesce(v_level,1)>=8 then raise exception 'pre-open speed-up is limited to players below level 8'; end if;
  select status into v_status from public.user_patrols where id=p_patrol_id and user_id=v_user for update;
  if v_status is null then raise exception 'patrol not found' using errcode='P0002'; end if;
  if v_status<>'ONGOING' then raise exception 'patrol is not eligible for speed-up'; end if;
  update public.user_patrols set status='CLAIMABLE',expires_at=now() where id=p_patrol_id and user_id=v_user;
  return jsonb_build_object('status','success','patrol_id',p_patrol_id,'currency','FREE_PREOPEN','cash_cost',0,'diamond_cost',0);
end $function$

CREATE OR REPLACE FUNCTION public.complete_patrol_v2(p_user_id uuid, p_patrol_id uuid, p_cash bigint, p_xp integer, p_course_name text, p_reward_item_id text, p_reward_qty integer, p_gear_dropped boolean, p_is_victory boolean, p_battle_reward_item_id text DEFAULT NULL::text, p_battle_reward_qty integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_exp TIMESTAMPTZ := now() + interval '24 hours';
BEGIN
    UPDATE public.user_patrols SET status = 'COMPLETED' WHERE id = p_patrol_id AND user_id = p_user_id;

    INSERT INTO public.presents (user_id, item_id, quantity, message, status, sent_at, expire_at)
    VALUES (p_user_id, 'CASH', p_cash, '見回り完了報酬 (' || p_course_name || CASE WHEN p_is_victory THEN '・バトル勝利' ELSE '' END || ')', 'UNCLAIMED', v_now, v_exp);

    IF p_reward_item_id IS NOT NULL AND p_reward_qty > 0 THEN
        INSERT INTO public.presents (user_id, item_id, quantity, message, status, sent_at, expire_at)
        VALUES (p_user_id, p_reward_item_id, p_reward_qty, '見回りドロップ報酬 (' || p_course_name || ')', 'UNCLAIMED', v_now, v_exp);
    END IF;

    IF p_gear_dropped THEN
        INSERT INTO public.presents (user_id, item_id, quantity, message, status, sent_at, expire_at)
        VALUES (p_user_id, 'WEAPON_001', 1, '見回り追加ドロップ装備 (' || p_course_name || ')', 'UNCLAIMED', v_now, v_exp);
    END IF;

    IF p_battle_reward_item_id IS NOT NULL AND p_battle_reward_qty > 0 THEN
        INSERT INTO public.presents (user_id, item_id, quantity, message, status, sent_at, expire_at)
        VALUES (p_user_id, p_battle_reward_item_id, p_battle_reward_qty, '見回りバトル勝利追加報酬 (' || p_course_name || ')', 'UNCLAIMED', v_now, v_exp);
    END IF;

    RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_tutorial_authentication(p_auth_method text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_auth_method text := upper(trim(p_auth_method));
  v_existing_method text;
  v_tutorial_step text;
  v_is_anonymous boolean := coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false);
  v_supported_identity_count integer;
  v_identity_provider text;
begin
  if v_user_id is null then raise exception 'Authentication is required'; end if;
  if v_is_anonymous then raise exception 'Verified authentication identity is required'; end if;
  if v_auth_method is null or v_auth_method not in ('EMAIL', 'GOOGLE') then raise exception 'Unsupported authentication method'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user_id::text, 0));
  select count(distinct identity.provider), min(identity.provider)
    into v_supported_identity_count, v_identity_provider
  from auth.identities identity
  where identity.user_id = v_user_id and identity.provider in ('email', 'google');
  if v_supported_identity_count <> 1 then raise exception 'Exactly one authentication identity is required'; end if;
  if v_identity_provider <> lower(v_auth_method) then raise exception 'Requested authentication identity is not linked'; end if;

  select methods.auth_method into v_existing_method
  from public.user_account_auth_methods methods where methods.user_id = v_user_id for update;
  select progress.step_id into v_tutorial_step
  from public.tutorial_progress progress where progress.user_id = v_user_id for update;

  if v_existing_method = v_auth_method and v_tutorial_step = 'AUTHENTICATION' then return 'AUTHENTICATION'; end if;
  if v_existing_method is not null and v_existing_method <> v_auth_method then raise exception 'A different authentication method is already linked'; end if;
  if v_tutorial_step <> 'COMPLETE' then raise exception 'Tutorial completion is required'; end if;

  insert into public.user_account_auth_methods(user_id, auth_method)
  values(v_user_id, v_auth_method)
  on conflict(user_id) do update set authenticated_at = now()
    where public.user_account_auth_methods.auth_method = excluded.auth_method;

  update public.tutorial_progress
  set step_id = 'AUTHENTICATION', authentication_pending = false, updated_at = now()
  where user_id = v_user_id;
  return 'AUTHENTICATION';
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_pvp_point(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_points integer;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT pvp_points INTO v_points FROM public.users WHERE id = p_user_id FOR UPDATE;
  IF v_points IS NULL THEN RAISE EXCEPTION 'user not found'; END IF;
  IF v_points < 1 THEN RAISE EXCEPTION 'insufficient pvp points'; END IF;
  UPDATE public.users SET pvp_points = pvp_points - 1,
    pvp_points_last_recovered_at = CASE WHEN pvp_points = 5 THEN now() ELSE pvp_points_last_recovered_at END
  WHERE id = p_user_id;
  RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_raid_attempt(p_user_id uuid, p_cost_type text, p_cost_amount integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user public.users%ROWTYPE;
    v_today DATE := CURRENT_DATE;
    v_reset_date DATE;
BEGIN
    SELECT * INTO v_user FROM public.users WHERE id = p_user_id FOR UPDATE;
    
    IF v_user.id IS NULL THEN
        RAISE EXCEPTION 'ユーザーが見つかりません。';
    END IF;

    IF p_cost_type = 'CASH' AND v_user.cash < p_cost_amount THEN
        RAISE EXCEPTION 'Cashが不足しています。';
    END IF;

    IF p_cost_type = 'DIAMOND' AND v_user.diamonds < p_cost_amount THEN
        RAISE EXCEPTION 'ダイヤが不足しています。';
    END IF;

    IF p_cost_type = 'CASH' THEN
        UPDATE public.users SET cash = cash - p_cost_amount WHERE id = p_user_id;
    END IF;
    IF p_cost_type = 'DIAMOND' THEN
        UPDATE public.users SET diamonds = diamonds - p_cost_amount WHERE id = p_user_id;
    END IF;

    v_reset_date := v_user.raid_attempts_reset_at::DATE;
    
    IF v_reset_date IS DISTINCT FROM v_today THEN
        UPDATE public.users SET raid_attempts_today = 1, raid_attempts_reset_at = now() WHERE id = p_user_id;
    ELSE
        UPDATE public.users SET raid_attempts_today = COALESCE(raid_attempts_today, 0) + 1 WHERE id = p_user_id;
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_tutorial_character_daily_free_gacha()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_today date := (clock_timestamp() at time zone 'Asia/Tokyo')::date;
  v_consumed integer := 0;
begin
  if new.gacha_id <> 'CHAR_NORMAL'
    or new.payment_source <> 'free'
    or new.pull_count <> 10
    or not exists (
      select 1
      from public.tutorial_progress progress
      where progress.user_id = new.user_id
        and progress.step_id = 'FREE_GACHA'
    ) then
    return new;
  end if;

  if exists (
    select 1
    from public.gacha_execution_history history
    where history.user_id = new.user_id
      and history.request_id = new.request_id
  ) then
    return new;
  end if;

  insert into public.user_daily_gacha_claims (
    user_id, gacha_type, last_claimed_date, updated_at
  ) values (
    new.user_id, 'CHARACTER', v_today, clock_timestamp()
  )
  on conflict (user_id, gacha_type) do update
  set last_claimed_date = excluded.last_claimed_date,
      updated_at = excluded.updated_at
  where public.user_daily_gacha_claims.last_claimed_date < excluded.last_claimed_date;

  get diagnostics v_consumed = row_count;
  if v_consumed <> 1 then
    raise exception 'daily free gacha already claimed' using errcode = '23505';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.consume_vitality_for_gvg(p_user_id uuid, p_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_vitality INTEGER;
BEGIN
    SELECT vitality INTO v_vitality FROM public.users WHERE id = p_user_id FOR UPDATE;

    IF v_vitality < p_cost THEN
        RAISE EXCEPTION '行動力が不足しています。';
    END IF;

    UPDATE public.users
    SET vitality = vitality - p_cost
    WHERE id = p_user_id;

    RETURN jsonb_build_object('success', true, 'consumed', p_cost);
END;
$function$

CREATE OR REPLACE FUNCTION public.converge_ranking_lifecycle_safety(p_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_orphan record;
  v_active public.ranking_seasons%rowtype;
  v_previous public.ranking_seasons%rowtype;
  v_orphans integer := 0;
  v_cutovers integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('ranking-lifecycle-safety-convergence',0));

  -- A non-Preview clean chain may have run 00227 and then the schema-only path
  -- of 00228. Reconcile only the immediately superseded row left by that pair.
  for v_orphan in
    select distinct on (closed.ranking_type) closed.*
    from public.ranking_seasons closed
    join public.ranking_seasons active
      on active.ranking_type=closed.ranking_type and active.status='ACTIVE'
     and active.starts_at<closed.ends_at+interval '1 second'
     and active.ends_at>closed.ends_at
     and abs(extract(epoch from (active.created_at-closed.updated_at)))<300
    where closed.ranking_type in ('PVP','RAID') and closed.status='CLOSED'
      and closed.ends_at<=p_at
      and not exists(select 1 from public.ranking_season_transition_audits audit where audit.season_id=closed.id)
      and not exists(select 1 from public.ranking_pvp_season_snapshots snapshot where snapshot.season_id=closed.id)
      and not exists(select 1 from public.ranking_raid_personal_season_snapshots snapshot where snapshot.season_id=closed.id)
      and not exists(select 1 from public.ranking_raid_guild_season_snapshots snapshot where snapshot.season_id=closed.id)
      and not exists(select 1 from public.ranking_season_reward_grants grant_row where grant_row.season_id=closed.id)
    order by closed.ranking_type,closed.ends_at desc
  loop
    if v_orphan.ranking_type='PVP' then
      perform public.assert_pvp_boundary_replay_continuity(v_orphan.id,p_at);
      perform public.finalize_pvp_season_rewards(v_orphan.id);
      perform public.reconcile_pvp_after_season_boundary(v_orphan.id,p_at);
    else
      perform public.finalize_raid_season_rewards(v_orphan.id);
      insert into public.ranking_season_transition_audits(
        season_id,ranking_type,replay_count,post_boundary_user_count,
        before_projection,expected_projection,after_projection
      ) values(v_orphan.id,'RAID',0,0,'[]','[]','[]')
      on conflict(season_id) do nothing;
    end if;
    v_orphans:=v_orphans+1;
  end loop;

  select * into v_active from public.ranking_seasons
  where ranking_type='RAID' and status='ACTIVE' and p_at>=starts_at and p_at<ends_at
  order by starts_at desc limit 1 for update;
  if found then
    select * into v_previous from public.ranking_seasons
    where ranking_type='RAID' and status='CLOSED'
      and starts_at<v_active.starts_at and ends_at>v_active.starts_at and ends_at<v_active.ends_at
    order by ends_at desc limit 1 for update;
    if found then
      if exists(select 1 from public.raid_damage_logs log
          where log.created_at>=v_active.starts_at and log.created_at<v_previous.ends_at) then
        raise exception 'Raid cutover overlap contains damage logs' using errcode='23514';
      end if;
      if exists(select 1 from public.ranking_season_reward_grants grant_row where grant_row.season_id=v_active.id)
        or exists(select 1 from public.ranking_raid_personal_season_snapshots snapshot where snapshot.season_id=v_active.id)
        or exists(select 1 from public.ranking_raid_guild_season_snapshots snapshot where snapshot.season_id=v_active.id)
        or exists(select 1 from public.pvp_ranking_reward_grants grant_row where grant_row.season_id=v_active.id)
        or exists(select 1 from public.gvg_guild_season_rankings ranking where ranking.season_id=v_active.id)
        or exists(select 1 from public.gvg_individual_season_rankings ranking where ranking.season_id=v_active.id) then
        raise exception 'Raid cutover active season already has dependencies' using errcode='23514';
      end if;
      if exists(select 1 from public.ranking_seasons other
          where other.id<>v_active.id and other.ranking_type='RAID'
            and other.starts_at=v_previous.ends_at) then
        raise exception 'Raid cutover target boundary already exists' using errcode='23505';
      end if;
      update public.ranking_seasons set starts_at=v_previous.ends_at,updated_at=clock_timestamp()
      where id=v_active.id;
      v_cutovers:=v_cutovers+1;
    end if;
  end if;
  return jsonb_build_object('orphanSeasons',v_orphans,'raidCutovers',v_cutovers);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_battle_replay_pending(p_battle_mode text, p_tactic_id text, p_random_seed bigint, p_player_snapshot jsonb, p_enemy_snapshot jsonb, p_source_reference_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user_id UUID := auth.uid(); v_id UUID; v_server_seed BIGINT;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication is required'; END IF;
  IF p_battle_mode NOT IN ('QUEST', 'PVP', 'RAID', 'GVG') THEN RAISE EXCEPTION 'Invalid battle mode'; END IF;
  IF p_tactic_id NOT IN ('ATTACK_PRIORITY', 'HEAL_PRIORITY', 'SKILL_PRIORITY', 'BALANCED', 'WEAKNESS_FOCUS') THEN RAISE EXCEPTION 'Invalid tactic'; END IF;
  IF jsonb_typeof(p_player_snapshot) <> 'array' OR jsonb_array_length(p_player_snapshot) NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Invalid player roster'; END IF;
  IF jsonb_typeof(p_enemy_snapshot) <> 'array' OR jsonb_array_length(p_enemy_snapshot) NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Invalid enemy roster'; END IF;
  v_server_seed := floor(random() * 2147483646)::BIGINT + 1;
  INSERT INTO public.battle_replay_sessions (
    requester_user_id, battle_mode, source_reference_id, tactic_id, random_seed, player_snapshot, enemy_snapshot
  ) VALUES (
    v_user_id, p_battle_mode, p_source_reference_id, p_tactic_id, v_server_seed, p_player_snapshot, p_enemy_snapshot
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_bbs_post(p_thread_id uuid, p_content text)
 RETURNS bbs_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_post public.bbs_posts;
  v_username TEXT;
  v_avatar_url TEXT;
BEGIN
  IF auth.uid() IS NULL OR p_thread_id IS NULL OR p_content IS NULL OR char_length(trim(p_content)) NOT BETWEEN 1 AND 200 OR NOT EXISTS (SELECT 1 FROM public.bbs_threads WHERE id = p_thread_id) THEN
    RAISE EXCEPTION 'Invalid BBS post';
  END IF;
  SELECT username, avatar_url INTO v_username, v_avatar_url FROM public.users WHERE id = auth.uid();
  INSERT INTO public.bbs_posts (thread_id, user_id, author_name, author_avatar_url, content)
  VALUES (p_thread_id, auth.uid(), COALESCE(v_username, 'Player'), v_avatar_url, trim(p_content))
  RETURNING * INTO v_post;
  UPDATE public.bbs_threads SET updated_at = now() WHERE id = p_thread_id;
  RETURN v_post;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_bbs_thread(p_category text, p_title text, p_content text)
 RETURNS bbs_threads
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_thread public.bbs_threads;
  v_username TEXT;
  v_avatar_url TEXT;
BEGIN
  IF auth.uid() IS NULL OR p_category NOT IN ('RECRUIT', 'STRATEGY_CHAT') OR p_title IS NULL OR p_content IS NULL OR char_length(trim(p_title)) NOT BETWEEN 1 AND 50 OR char_length(trim(p_content)) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Invalid BBS thread';
  END IF;
  SELECT username, avatar_url INTO v_username, v_avatar_url FROM public.users WHERE id = auth.uid();
  INSERT INTO public.bbs_threads (category, title, content, user_id, author_name, author_avatar_url)
  VALUES (p_category, trim(p_title), trim(p_content), auth.uid(), COALESCE(v_username, 'Player'), v_avatar_url)
  RETURNING * INTO v_thread;
  RETURN v_thread;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_guild(p_user_id uuid, p_guild_name text, p_guild_description text, p_guild_logo text, p_guild_color text, p_creation_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_cash INTEGER;
    v_new_guild_id UUID;
BEGIN
    SELECT cash INTO v_cash FROM public.users WHERE id = p_user_id;
    IF v_cash IS NULL OR v_cash < p_creation_cost THEN
        RETURN jsonb_build_object('error', 'キャッシュが不足しています。');
    END IF;

    INSERT INTO public.guilds (name, description, logo_icon, color_theme, level, xp, cash, approval_required, auto_kick_days)
    VALUES (p_guild_name, p_guild_description, COALESCE(p_guild_logo, 'guild_icon_default.png'), COALESCE(p_guild_color, 'red'), 1, 0, 0, false, 7)
    RETURNING id INTO v_new_guild_id;

    INSERT INTO public.guild_members (guild_id, user_id, role)
    VALUES (v_new_guild_id, p_user_id, 'MASTER');

    UPDATE public.users SET cash = cash - p_creation_cost, guild_id = v_new_guild_id WHERE id = p_user_id;

    PERFORM public.evaluate_mission_progress(p_user_id, 'GUILD_JOIN', 1);
    RETURN jsonb_build_object('guild_id', v_new_guild_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_guild_v2(p_user_id uuid, p_guild_name text, p_creation_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user public.users%rowtype; v_name text:=trim(coalesce(p_guild_name,'')); v_guild uuid;
begin
 if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'Only the current user can create a guild' using errcode='42501'; end if;
 if char_length(v_name) not between 1 and 12 or p_creation_cost<>500 then raise exception 'Invalid guild creation request' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':guild-create',0));
 select * into v_user from public.users where id=auth.uid() for update;
 if not found or v_user.level<5 or v_user.cash<500 then raise exception 'Guild creation requirements are not met' using errcode='P0001'; end if;
 if v_user.guild_id is not null or exists(select 1 from public.guild_members where user_id=auth.uid()) then raise exception 'Leave the current guild before creating another guild' using errcode='23505'; end if;
 perform 1 from public.guilds where lower(trim(name))=lower(v_name) and not is_disbanded for update;
 if found then raise exception 'Guild name is already in use' using errcode='23505'; end if;
 update public.guild_join_requests set status='CANCELLED',reviewed_at=now(),reviewed_by=auth.uid() where user_id=auth.uid() and status='PENDING';
 insert into public.guilds(name,leader_id,level,xp,funds,recruitment_mode,approval_required) values(v_name,auth.uid(),1,0,0,'OPEN_JOIN',false) returning id into v_guild;
 insert into public.guild_members(guild_id,user_id,role,weekly_contribution,total_contribution) values(v_guild,auth.uid(),'MASTER',0,0);
 update public.users set cash=cash-500,guild_id=v_guild where id=auth.uid();
 perform public.evaluate_mission_progress(auth.uid(),'GUILD_JOIN',1);
 return jsonb_build_object('status','success','guild_id',v_guild,'cash_spent',500);
end $function$

CREATE OR REPLACE FUNCTION public.create_gvg_match_session(p_session_key text, p_scheduled_start_at timestamp with time zone, p_scheduled_end_at timestamp with time zone, p_guild_a_id uuid, p_guild_b_id uuid, p_guild_a_phase_hp bigint, p_guild_b_phase_hp bigint, p_npc_guild_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_match_id UUID;
BEGIN
  IF p_scheduled_end_at <= p_scheduled_start_at THEN RAISE EXCEPTION 'Invalid GvG schedule'; END IF;
  IF p_guild_a_phase_hp < 1 OR p_guild_b_phase_hp < 1 THEN RAISE EXCEPTION 'Invalid GvG phase HP'; END IF;
  IF p_guild_b_id IS NOT NULL AND p_guild_a_id = p_guild_b_id THEN RAISE EXCEPTION 'A guild cannot match itself'; END IF;
  IF EXISTS (
    SELECT 1 FROM public.gvg_match_sessions existing
    WHERE existing.session_key = p_session_key
      AND (existing.guild_a_id IN (p_guild_a_id, p_guild_b_id) OR existing.guild_b_id IN (p_guild_a_id, p_guild_b_id))
      AND existing.status IN ('MATCHING', 'CONFIRMED', 'ACTIVE')
  ) THEN RAISE EXCEPTION 'Guild already has a match in this GvG slot'; END IF;

  INSERT INTO public.gvg_match_sessions (
    session_key, scheduled_start_at, scheduled_end_at, status, is_npc_match,
    guild_a_id, guild_b_id, npc_guild_name,
    guild_a_phase_max_hp, guild_b_phase_max_hp, guild_a_phase_hp, guild_b_phase_hp
  ) VALUES (
    p_session_key, p_scheduled_start_at, p_scheduled_end_at, 'MATCHING', p_guild_b_id IS NULL,
    p_guild_a_id, p_guild_b_id, p_npc_guild_name,
    p_guild_a_phase_hp, p_guild_b_phase_hp, p_guild_a_phase_hp, p_guild_b_phase_hp
  ) RETURNING id INTO v_match_id;

  PERFORM public.snapshot_gvg_match_members(v_match_id);
  RETURN v_match_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_kpi_marketing_import_batch_v1(p_source text, p_actor_identifier uuid, p_file_hash text, p_idempotency_key text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_row public.kpi_marketing_import_batches%rowtype; v_admin boolean;
begin
  v_admin := auth.jwt()->>'role'='service_role' or coalesce(auth.jwt()->'app_metadata'->>'role','')='admin';
  if not v_admin or p_source not in ('x_ads_manager_manual','x_ads_manager_import')
    or p_actor_identifier is null or (p_file_hash is not null and p_file_hash !~ '^[a-f0-9]{64}$')
    or p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_.:-]{1,128}$'
    or not public.kpi_v249_metadata_valid(p_metadata)
    or (auth.jwt()->>'role'<>'service_role' and p_actor_identifier is distinct from auth.uid()) then
    raise exception 'Invalid marketing batch request' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('kpi249:marketing-batch:'||p_idempotency_key,0));
  select * into v_row from public.kpi_marketing_import_batches where idempotency_key=p_idempotency_key;
  if found then
    if v_row.source is distinct from p_source or v_row.actor_identifier is distinct from p_actor_identifier
      or v_row.file_hash is distinct from p_file_hash or v_row.metadata is distinct from p_metadata then
      raise exception 'Conflicting marketing batch retry' using errcode='23505'; end if;
    return v_row.id; end if;
  insert into public.kpi_marketing_import_batches(platform,source,actor_identifier,file_hash,idempotency_key,metadata)
  values('X',p_source,p_actor_identifier,p_file_hash,p_idempotency_key,p_metadata) returning * into v_row;
  return v_row.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_patrol_battle_replay(p_patrol_id uuid, p_tactic_id text DEFAULT 'ATTACK_PRIORITY'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_patrol public.user_patrols%rowtype; v_ids text[]; v_player jsonb; v_enemy jsonb; v_replay uuid; v_seed bigint; v_enemy_tactic text;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
 if p_tactic_id not in('ATTACK_PRIORITY','HEAL_PRIORITY','SKILL_PRIORITY','BALANCED','WEAKNESS_FOCUS') then raise exception 'invalid tactic' using errcode='22023'; end if;
 select * into v_patrol from public.user_patrols where id=p_patrol_id and user_id=v_uid and (status='CLAIMABLE' or(status='ONGOING' and expires_at<=now())) and has_battle_event and not coalesce(battle_resolved,false) for update;
 if not found or v_patrol.encounter_snapshot is null then raise exception 'eligible patrol encounter not found' using errcode='P0002'; end if;
 update public.user_patrols set status='CLAIMABLE' where id=p_patrol_id and status='ONGOING';
 select array_remove(array[d.character_1_id::text,d.character_2_id::text,d.character_3_id::text,d.character_4_id::text,d.character_5_id::text],null) into v_ids from public.pvp_defense_decks d where d.user_id=v_uid;
 if coalesce(cardinality(v_ids),0)=0 then select array[o.id::text] into v_ids from public.user_characters o where o.user_id=v_uid and o.character_id=v_patrol.character_id order by o.created_at limit 1; end if;
 v_player:=public.build_server_battle_snapshot(v_uid,v_ids,'PLAYER'); v_enemy:=v_patrol.encounter_snapshot->'members';
 v_enemy := public.apply_tutorial_enemy_snapshot(v_uid, v_player, v_enemy); v_enemy_tactic:=coalesce(v_patrol.encounter_snapshot->>'enemyTactic','BALANCED'); v_seed:=floor(random()*2147483646)::bigint+1;
 insert into public.battle_replay_sessions(requester_user_id,battle_mode,source_reference_id,tactic_id,enemy_tactic_id,random_seed,player_snapshot,enemy_snapshot,resolution_authority) values(v_uid,'QUEST',p_patrol_id,p_tactic_id,v_enemy_tactic,v_seed,v_player,v_enemy,'PATROL_SERVER') returning id into v_replay;
 return jsonb_build_object('replay_session_id',v_replay,'player_snapshot',v_player,'enemy_snapshot',v_enemy,'enemy_tactic',v_enemy_tactic);
end $function$

CREATE OR REPLACE FUNCTION public.current_gameplay_reset_eligibility(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_user_id is null or not exists(select 1 from public.users where id=p_user_id) then
    return jsonb_build_object('eligible',false,'reason','UNSUPPORTED');
  end if;
  if exists(select 1 from public.payment_transactions where user_id=p_user_id)
    or exists(select 1 from public.user_shop_purchases where user_id=p_user_id)
    or exists(select 1 from public.user_monthly_passes where user_id=p_user_id) then
    return jsonb_build_object('eligible',false,'reason','PAYMENT');
  end if;
  if exists(select 1 from public.guild_members where user_id=p_user_id)
    or exists(select 1 from public.guilds where leader_id=p_user_id) then
    return jsonb_build_object('eligible',false,'reason','GUILD');
  end if;
  if exists(select 1 from public.user_patrols where user_id=p_user_id and status<>'COMPLETED')
    or exists(select 1 from public.battle_replay_sessions where requester_user_id=p_user_id
      and (status='PENDING' or finalization_status='PENDING')) then
    return jsonb_build_object('eligible',false,'reason','ACTIVE_GAMEPLAY');
  end if;
  if not exists(select 1 from public.user_lifetime_onboarding_grants where user_id=p_user_id) then
    return jsonb_build_object('eligible',false,'reason','UNSUPPORTED');
  end if;
  return jsonb_build_object('eligible',true,'reason',null);
end;
$function$

CREATE OR REPLACE FUNCTION public.defer_tutorial_authentication()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_progress public.tutorial_progress%rowtype;
begin
  if v_user_id is null then
    raise exception 'Authentication is required' using errcode = '28000';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_user_id::text, 0));

  select * into v_progress
  from public.tutorial_progress
  where user_id = v_user_id
  for update;

  if not found or v_progress.step_id <> 'COMPLETE' then
    raise exception 'Tutorial completion is required' using errcode = '23514';
  end if;
  if v_progress.authentication_pending then
    return 'COMPLETE';
  end if;
  if coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) is not true
     or not exists(select 1 from auth.users where id = v_user_id and is_anonymous is true) then
    raise exception 'Only the current anonymous account can defer authentication' using errcode = '42501';
  end if;
  if exists(select 1 from public.user_account_auth_methods where user_id = v_user_id)
     or exists(select 1 from auth.identities where user_id = v_user_id and provider <> 'anonymous') then
    raise exception 'A connected identity cannot defer authentication' using errcode = '42501';
  end if;

  update public.tutorial_progress
  set authentication_pending = true,
      completed_at = coalesce(completed_at, now()),
      updated_at = now()
  where user_id = v_user_id;

  return 'COMPLETE';
end;
$function$

CREATE OR REPLACE FUNCTION public.discard_current_anonymous_account_for_switch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_auth_user auth.users%rowtype;
  v_deleted_public integer := 0;
  v_deleted_auth integer := 0;
begin
  if v_user_id is null then
    raise exception 'Authentication is required' using errcode = '28000';
  end if;

  select * into v_auth_user
  from auth.users
  where id = v_user_id
  for update;

  if not found then
    raise exception 'Authenticated user was not found' using errcode = 'P0002';
  end if;
  if v_auth_user.is_anonymous is not true
     or coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) is not true then
    raise exception 'Only the current anonymous account can be discarded' using errcode = '42501';
  end if;

  perform 1 from public.users where id = v_user_id for update;
  if not found then
    raise exception 'Anonymous gameplay profile was not found' using errcode = 'P0002';
  end if;

  if exists(select 1 from public.user_account_auth_methods row where row.user_id = v_user_id)
     or exists(select 1 from auth.identities row where row.user_id = v_user_id and row.provider <> 'anonymous') then
    raise exception 'A formally connected identity cannot be discarded' using errcode = '42501';
  end if;

  -- External, competitive, guild, invite and financial attribution must never
  -- be cascaded by account switching. Operations review is required instead.
  if exists(select 1 from public.payment_transactions row where row.user_id = v_user_id)
     or exists(select 1 from public.user_monthly_passes row where row.user_id = v_user_id)
     or exists(select 1 from public.user_invitations row where row.inviter_user_id = v_user_id or row.invitee_user_id = v_user_id)
     or exists(select 1 from public.user_friends row where row.user_id = v_user_id or row.friend_id = v_user_id)
     or exists(select 1 from public.guild_members row where row.user_id = v_user_id)
     or exists(select 1 from public.guilds row where row.leader_id = v_user_id)
     or exists(select 1 from public.guild_exp_daily_ledger row where row.user_id = v_user_id)
     or exists(select 1 from public.guild_exp_daily_progress row where row.user_id = v_user_id)
     or exists(select 1 from public.raid_damage_logs row where row.user_id = v_user_id)
     or exists(select 1 from public.raid_reward_grants row where row.user_id = v_user_id)
     or exists(select 1 from public.raid_production_reward_grants row where row.user_id = v_user_id)
     or exists(select 1 from public.raid_completion_xp_grants row where row.user_id = v_user_id)
     or exists(select 1 from public.raid_instance_user_progress row where row.user_id = v_user_id)
     or exists(select 1 from public.user_raid_daily_attempts row where row.user_id = v_user_id)
     or exists(select 1 from public.pvp_defense_logs row where row.user_id = v_user_id)
     or exists(select 1 from public.pvp_ranking_reward_grants row where row.user_id = v_user_id)
     or exists(select 1 from public.pvp_daily_wins row where row.user_id = v_user_id)
     or exists(select 1 from public.gvg_attack_logs row where row.attacker_user_id = v_user_id)
     or exists(select 1 from public.gvg_individual_season_rankings row where row.user_id = v_user_id) then
    raise exception 'Anonymous account has protected history and cannot be discarded' using errcode = '55000';
  end if;

  delete from public.users where id = v_user_id;
  get diagnostics v_deleted_public = row_count;
  if v_deleted_public <> 1 then
    raise exception 'Anonymous gameplay profile discard did not complete' using errcode = 'P0001';
  end if;

  delete from auth.users where id = v_user_id;
  get diagnostics v_deleted_auth = row_count;
  if v_deleted_auth <> 1 then
    raise exception 'Anonymous auth account discard did not complete' using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'status', 'DISCARDED',
    'discardedUserId', v_user_id,
    'gameplayMerged', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.donate_to_guild(p_user_id uuid, p_guild_id uuid, p_amount integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cash bigint;v_inserted integer;v_result jsonb;v_day date:=public.guild_jst_date();
begin if auth.uid() is null or auth.uid()<>p_user_id or p_amount<>5000 then raise exception 'Invalid Production donation'; end if;
 if not exists(select 1 from public.guild_members where guild_id=p_guild_id and user_id=auth.uid()) then raise exception 'Guild membership required'; end if;
 select cash into v_cash from public.users where id=auth.uid() for update; if v_cash<5000 then raise exception 'Insufficient cash'; end if;
 perform 1 from public.guilds where id=p_guild_id and not is_disbanded for update; if not found then raise exception 'Active guild not found'; end if;
 insert into public.guild_exp_daily_ledger(guild_id,user_id,source,jst_date,exp_granted) values(p_guild_id,auth.uid(),'DONATION',v_day,20)
 on conflict(guild_id,user_id,source,jst_date) do nothing; get diagnostics v_inserted=row_count;
 if v_inserted=0 then raise exception 'Guild donation already completed today'; end if;
 update public.users set cash=cash-5000 where id=auth.uid() returning cash into v_cash;
 update public.guilds set funds=coalesce(funds,0)+5000 where id=p_guild_id;
 v_result:=public.apply_canonical_guild_exp(p_guild_id,20);
 return jsonb_build_object('status','success','next_cash',v_cash,'xp_gained',20,'guild',v_result); end $function$

CREATE OR REPLACE FUNCTION public.enforce_canonical_guild_join_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_level integer;
begin
 select level into v_level from public.users where id=new.user_id;
 if coalesce(v_level,0)<3 then raise exception 'Guild joining requires user level 3' using errcode='42501'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.enforce_guild_member_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_level INTEGER;
  v_cap INTEGER;
  v_count INTEGER;
BEGIN
  IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
  SELECT level INTO v_level FROM public.guilds WHERE id = NEW.guild_id FOR UPDATE;
  IF v_level IS NULL THEN RAISE EXCEPTION 'Guild not found'; END IF;
  SELECT max_members INTO v_cap FROM public.guild_level_master WHERE level = v_level;
  v_cap := LEAST(COALESCE(v_cap, 10), 20);
  SELECT count(*) INTO v_count FROM public.guild_members WHERE guild_id = NEW.guild_id;
  IF v_count >= v_cap THEN RAISE EXCEPTION 'Guild member limit reached (% members)', v_cap; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_kpi_classification_no_overlap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if exists (
    select 1
    from public.kpi_account_classification_periods existing
    where existing.subject_id = new.subject_id
      and existing.id <> coalesce(new.id, -1)
      and tstzrange(existing.valid_from, coalesce(existing.valid_to, 'infinity'::timestamptz), '[)')
          && tstzrange(new.valid_from, coalesce(new.valid_to, 'infinity'::timestamptz), '[)')
  ) then
    raise exception 'KPI classification periods overlap' using errcode = '23P01';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_mission_claim_prerequisite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_prerequisite text;
begin
  if new.status='CLAIMED' and old.status is distinct from 'CLAIMED' then
    select prerequisite_mission_id into v_prerequisite from public.missions where id=new.mission_id;
    if v_prerequisite is not null and not exists(
      select 1 from public.user_missions prerequisite
      where prerequisite.user_id=new.user_id and prerequisite.mission_id=v_prerequisite
        and prerequisite.status='CLAIMED'
    ) then raise exception 'mission prerequisite is not claimed' using errcode='23514'; end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.ensure_current_player_profile()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_name text;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT username INTO v_name FROM public.users WHERE id = v_user_id;
  IF v_name IS NULL THEN
    v_name := 'u' || substring(replace(v_user_id::text, '-', '') FROM 1 FOR 7);
    INSERT INTO public.users (id, username, current_base_id, favorite_character_id)
    VALUES (v_user_id, v_name, 'neon_tower', '11111111-1111-1111-1111-111111111111')
    ON CONFLICT (id) DO NOTHING;
  END IF;
  RETURN v_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.equip_character_cosmetic(p_user_character_id uuid, p_slot text, p_cosmetic_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_characters WHERE id = p_user_character_id AND user_id = v_user_id) THEN
    RAISE EXCEPTION 'character is not owned by the current user';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.character_cosmetics cc
    JOIN public.cosmetic_master cm ON cm.id = cc.cosmetic_id
    WHERE cc.user_character_id = p_user_character_id
      AND cc.cosmetic_id = p_cosmetic_id
      AND cm.owner_scope = 'CHARACTER'
      AND cm.slot = p_slot
      AND (cc.expires_at IS NULL OR cc.expires_at > now())
  ) THEN
    RAISE EXCEPTION 'cosmetic is not owned or is unavailable';
  END IF;

  INSERT INTO public.equipped_cosmetics (user_id, slot, cosmetic_id)
  VALUES (v_user_id, 'CHARACTER:' || p_user_character_id::text || ':' || p_slot, p_cosmetic_id)
  ON CONFLICT (user_id, slot) DO UPDATE
  SET cosmetic_id = EXCLUDED.cosmetic_id, equipped_at = now();

  RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.equip_gear_bulk(p_character_id text, p_user_id uuid, p_gear_ids jsonb)
