  return coalesce((
    select claim.reward_payload
    from public.canonical_daily_activity_claims claim
    where claim.user_id = v_user_id
      and claim.source_key = 'RAID_BATTLE:' || p_replay_id::text
      and claim.source_ref = p_replay_id
