      where views.user_id=v_uid and views.event_id=event.id and views.jst_date=v_today)
  order by event.start_at limit 1;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_preopen_guild_power_ranking(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_season public.ranking_seasons%rowtype;
  v_master public.ranking_guild_power_season_master%rowtype;
  v_my_guild_id uuid;
  v_rows jsonb:='[]'::jsonb;
  v_self jsonb;
  v_updated_at timestamptz;
  v_is_final boolean;
  v_is_current_context boolean;
begin
  if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then
    raise exception 'invalid pagination' using errcode='22023';
  end if;
  select master.* into strict v_master from public.ranking_guild_power_season_master master
  where master.event_key='PREOPEN_GUILD_POWER_2026';
  select * into strict v_season from public.ranking_seasons where id=v_master.season_id;
  if clock_timestamp()>=v_season.starts_at and v_season.status='PREPARING' then
    perform public.activate_preopen_guild_power_season();
    select * into strict v_season from public.ranking_seasons where id=v_master.season_id;
  end if;
  if clock_timestamp()>=v_season.ends_at and v_season.status<>'CLOSED' then
    perform public.finalize_preopen_guild_power_season();
    select * into strict v_season from public.ranking_seasons where id=v_master.season_id;
  end if;
  select member.guild_id into v_my_guild_id from public.guild_members member
  where member.user_id=v_uid;
  v_is_final:=v_season.status='CLOSED';
  v_is_current_context:=clock_timestamp()>=v_season.starts_at and not exists(
    select 1 from public.ranking_seasons newer
    where newer.ranking_type=v_season.ranking_type
      and newer.starts_at>v_season.starts_at
  );

  if v_is_final then
    select coalesce(jsonb_agg(to_jsonb(page) order by page.rank_position,page.guild_id),'[]'::jsonb)
    into v_rows from (
      select snapshot.guild_id,snapshot.guild_name name,snapshot.total_power current_power,
        snapshot.total_power score,snapshot.member_count,snapshot.rank_position,snapshot.snapshotted_at updated_at
      from public.ranking_guild_power_season_snapshots snapshot
      where snapshot.season_id=v_season.id
      order by snapshot.rank_position,snapshot.guild_id limit p_limit offset p_offset
    ) page;
    select to_jsonb(self_row) into v_self from (
      select snapshot.guild_id,snapshot.guild_name name,snapshot.total_power current_power,
        snapshot.total_power score,snapshot.member_count,snapshot.rank_position,snapshot.snapshotted_at updated_at
      from public.ranking_guild_power_season_snapshots snapshot
      where snapshot.season_id=v_season.id and snapshot.guild_id=v_my_guild_id
    ) self_row;
    select max(snapshot.snapshotted_at) into v_updated_at
    from public.ranking_guild_power_season_snapshots snapshot where snapshot.season_id=v_season.id;
  elsif clock_timestamp()>=v_season.starts_at and clock_timestamp()<v_season.ends_at then
    with totals as (
      select guild.id guild_id,guild.name,
        sum(public.calculate_user_total_power(member.user_id))::bigint current_power,
        count(*)::integer member_count
      from public.guilds guild join public.guild_members member on member.guild_id=guild.id
      where not exists(select 1 from public.ranking_guild_exclusions exclusion where exclusion.guild_id=guild.id)
      group by guild.id,guild.name
      having sum(public.calculate_user_total_power(member.user_id))>0
    ), ranked as (
      select totals.*,totals.current_power score,
        rank() over(order by totals.current_power desc)::integer rank_position,
        row_number() over(order by totals.current_power desc,totals.guild_id)::integer row_position
      from totals
    )
    select
      coalesce(
        jsonb_agg(to_jsonb(ranked)-'row_position' order by ranked.rank_position,ranked.guild_id)
          filter(where ranked.row_position>p_offset and ranked.row_position<=p_offset+p_limit),
        '[]'::jsonb
      ),
      (jsonb_agg(to_jsonb(ranked)-'row_position')
        filter(where ranked.guild_id=v_my_guild_id))->0
    into v_rows,v_self
    from ranked;
    v_updated_at:=clock_timestamp();
  else
    -- Before opening or during the short server-only finalization interval.
    v_rows:='[]'::jsonb;
    v_self:=null;
    v_updated_at:=v_season.updated_at;
  end if;

  return jsonb_build_object(
    'season_id',v_season.id,'event_key',v_master.event_key,
    'display_name',v_master.display_name,'display_period_text',v_master.display_period_text,
    'starts_at',v_season.starts_at,'ends_at',v_season.ends_at,'status',v_season.status,
    'is_finalized',v_is_final,'is_current_context',v_is_current_context,
    'server_updated_at',v_updated_at,
    'rows',v_rows,'self_guild',v_self
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_public_battle_loadout(p_target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user record;
  v_char record;
  v_equips jsonb;
  v_skills jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT username INTO v_user FROM public.users WHERE id = p_target_user_id;
  SELECT id, character_id, level, awakening_level INTO v_char
  FROM public.user_characters
  WHERE user_id = p_target_user_id
  ORDER BY level DESC, awakening_level DESC, id
  LIMIT 1;
  IF v_char.id IS NULL THEN
    RETURN jsonb_build_object('username', v_user.username, 'character', null, 'equipments', '[]'::jsonb, 'skills', '[]'::jsonb);
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'equipment_id', equipment_id, 'level', level, 'plus_val', plus_val, 'slot_index', slot_index, 'random_options', random_options
  )), '[]'::jsonb) INTO v_equips
  FROM public.user_equipments WHERE user_id = p_target_user_id AND equipped_character_id = v_char.id::text;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'skill_card_id', skill_card_id, 'plus_val', plus_val, 'slot_index', slot_index
  )), '[]'::jsonb) INTO v_skills
  FROM public.user_skills WHERE user_id = p_target_user_id AND equipped_character_id = v_char.id::text;

  RETURN jsonb_build_object(
    'username', v_user.username,
    'character', jsonb_build_object('id', v_char.id, 'character_id', v_char.character_id, 'level', v_char.level, 'awakening_level', v_char.awakening_level),
    'equipments', v_equips,
    'skills', v_skills
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_public_battle_roster(p_target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user record;
  v_roster jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_target_user_id IS NULL THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  SELECT username INTO v_user FROM public.users WHERE id = p_target_user_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id,
    'character_id', c.character_id,
    'level', c.level,
    'awakening_level', c.awakening_level,
    'equipments', COALESCE((SELECT jsonb_agg(jsonb_build_object('equipment_id', e.equipment_id, 'level', e.level, 'plus_val', e.plus_val, 'slot_index', e.slot_index, 'random_options', e.random_options)) FROM public.user_equipments e WHERE e.user_id = c.user_id AND e.equipped_character_id = c.id::text), '[]'::jsonb),
    'skills', COALESCE((SELECT jsonb_agg(jsonb_build_object('skill_card_id', s.skill_card_id, 'plus_val', s.plus_val, 'slot_index', s.slot_index)) FROM public.user_skills s WHERE s.user_id = c.user_id AND s.equipped_character_id = c.id::text), '[]'::jsonb)
  ) ORDER BY c.level DESC, c.awakening_level DESC), '[]'::jsonb) INTO v_roster
  FROM public.user_characters c WHERE c.user_id = p_target_user_id;
  RETURN jsonb_build_object('username', v_user.username, 'characters', v_roster);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_public_battle_roster_by_character_ids(p_character_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_roster jsonb;
BEGIN
  IF auth.uid() IS NULL OR p_character_ids IS NULL OR cardinality(p_character_ids) = 0 THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', c.id, 'character_id', c.character_id, 'level', c.level, 'awakening_level', c.awakening_level,
    'equipments', COALESCE((SELECT jsonb_agg(jsonb_build_object('equipment_id', e.equipment_id, 'level', e.level, 'plus_val', e.plus_val, 'slot_index', e.slot_index, 'random_options', e.random_options)) FROM public.user_equipments e WHERE e.user_id = c.user_id AND e.equipped_character_id = c.id::text), '[]'::jsonb),
    'skills', COALESCE((SELECT jsonb_agg(jsonb_build_object('skill_card_id', s.skill_card_id, 'plus_val', s.plus_val, 'slot_index', s.slot_index)) FROM public.user_skills s WHERE s.user_id = c.user_id AND s.equipped_character_id = c.id::text), '[]'::jsonb)
  ) ORDER BY array_position(p_character_ids, c.id)), '[]'::jsonb) INTO v_roster
  FROM public.user_characters c WHERE c.id = ANY(p_character_ids);
  RETURN v_roster;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_public_guild_power_rankings(p_daily boolean, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz; v_end timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
  v_start:=date_trunc('day',clock_timestamp() at time zone 'Asia/Tokyo') at time zone 'Asia/Tokyo'; v_end:=v_start+interval '1 day';
  return coalesce((select jsonb_agg(to_jsonb(ranked) order by ranked.rank_position) from (
    select aggregated.*,dense_rank() over(order by aggregated.score desc,aggregated.guild_id) rank_position from (
      select guild.id guild_id,guild.name,
        sum(power.total_power)::bigint current_power,
        coalesce(sum(power.total_power) filter(where player.last_active_at>=v_start and player.last_active_at<v_end),0)::bigint daily_power,
        count(*)::integer member_count,
        count(*) filter(where player.last_active_at>=v_start and player.last_active_at<v_end)::integer active_member_count,
        case when p_daily then coalesce(sum(power.total_power) filter(where player.last_active_at>=v_start and player.last_active_at<v_end),0) else sum(power.total_power) end::bigint score
      from public.guilds guild join public.guild_members member on member.guild_id=guild.id
      join public.users player on player.id=member.user_id join public.user_power_rankings power on power.user_id=member.user_id
      group by guild.id,guild.name
    ) aggregated where not p_daily or aggregated.active_member_count>0
    order by score desc,guild_id limit p_limit offset p_offset
  ) ranked),'[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_public_leader_characters(p_user_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR p_user_ids IS NULL OR cardinality(p_user_ids) = 0 THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(to_jsonb(x)) FROM (
      SELECT DISTINCT ON (c.user_id) c.user_id, c.id, c.character_id, c.level
      FROM public.user_characters c
      WHERE c.user_id = ANY(p_user_ids)
      ORDER BY c.user_id, c.level DESC, c.awakening_level DESC, c.id
    ) x
  ), '[]'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_public_power_rankings(p_daily boolean, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_start timestamptz; v_end timestamptz;
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
  v_start:=date_trunc('day',clock_timestamp() at time zone 'Asia/Tokyo') at time zone 'Asia/Tokyo'; v_end:=v_start+interval '1 day';
  return coalesce((select jsonb_agg(to_jsonb(row_data) order by row_data.rank_position) from (
    select ranking.user_id,player.username,player.avatar_url,ranking.total_power current_power,ranking.updated_at,
      member.guild_id,guild.name guild_name,
      dense_rank() over(order by ranking.total_power desc,ranking.updated_at asc) rank_position,
      (player.last_active_at>=v_start and player.last_active_at<v_end) is_daily_active
    from public.user_power_rankings ranking join public.users player on player.id=ranking.user_id
    left join public.guild_members member on member.user_id=ranking.user_id left join public.guilds guild on guild.id=member.guild_id
    where not p_daily or (player.last_active_at>=v_start and player.last_active_at<v_end)
    order by ranking.total_power desc,ranking.updated_at asc limit p_limit offset p_offset
  ) row_data),'[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_public_pvp_rankings(p_daily boolean, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_today date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date; v_season uuid:=public.current_ranking_season_id('PVP');
begin
  if auth.uid() is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
  return coalesce((select jsonb_agg(to_jsonb(ranked) order by ranked.rank_position) from (
    select row_data.*,dense_rank() over(order by row_data.score desc,row_data.user_id) rank_position from (
      select rank.user_id,player.username,player.avatar_url,coalesce(rank.rank_points,1000) rank_points,
        coalesce(daily.wins,0) daily_wins,coalesce(power.total_power,0) current_power,
        member.guild_id,guild.name guild_name,v_season season_id,
        case when p_daily then coalesce(daily.wins,0) else coalesce(rank.rank_points,1000) end score
      from public.pvp_ranks rank join public.users player on player.id=rank.user_id
      left join public.pvp_daily_wins daily on daily.user_id=rank.user_id and daily.activity_date=v_today
      left join public.user_power_rankings power on power.user_id=rank.user_id
      left join public.guild_members member on member.user_id=rank.user_id left join public.guilds guild on guild.id=member.guild_id
    ) row_data order by score desc,user_id limit p_limit offset p_offset
  ) ranked),'[]'::jsonb);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_pvp_rankings_page(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid();
begin if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if; if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
 return jsonb_build_object('rows',coalesce((with totals as(select rank.user_id,u.username,rank.rank_points score,rank.updated_at achieved_at,coalesce(power.total_power,0) total_power from public.pvp_ranks rank join public.users u on u.id=rank.user_id left join public.user_power_rankings power on power.user_id=rank.user_id),ranked as(select *,rank() over(order by score desc) rank_position from totals) select jsonb_agg(to_jsonb(page) order by score desc,achieved_at,user_id) from(select * from ranked order by score desc,achieved_at,user_id limit p_limit offset p_offset)page),'[]'::jsonb),'selfRank',(with totals as(select user_id,rank_points score,updated_at achieved_at from public.pvp_ranks),ranked as(select *,rank() over(order by score desc) rank_position from totals) select to_jsonb(ranked) from ranked where user_id=v_uid));
end $function$

CREATE OR REPLACE FUNCTION public.get_raid_rankings(p_instance_id uuid, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_uid uuid:=auth.uid(); v_day text;
begin
 if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if; if p_limit not between 1 and 100 or p_offset not between 0 and 10000 then raise exception 'invalid pagination' using errcode='22023'; end if;
 select raid_day_key into v_day from public.raid_bosses where id=p_instance_id; if v_day is null then raise exception 'Raid day not found' using errcode='P0002'; end if;
 return jsonb_build_object(
 'individual',coalesce((with totals as(select log.user_id,u.username,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day join public.users u on u.id=log.user_id group by log.user_id,u.username),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select jsonb_agg(to_jsonb(page)order by contribution desc,achieved_at,user_id)from(select * from ranked order by contribution desc,achieved_at,user_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'guild',coalesce((with totals as(select log.guild_id,g.name guild_name,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at,count(distinct log.user_id)::integer participant_count from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day join public.guilds g on g.id=log.guild_id where log.guild_id is not null group by log.guild_id,g.name),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select jsonb_agg(to_jsonb(page)order by contribution desc,achieved_at,guild_id)from(select * from ranked order by contribution desc,achieved_at,guild_id limit p_limit offset p_offset)page),'[]'::jsonb),
 'selfRank',(with totals as(select log.user_id,sum(log.raw_damage)::bigint contribution,min(log.created_at) achieved_at from public.raid_damage_logs log join public.raid_bosses boss on boss.id=log.raid_boss_instance_id and boss.raid_day_key=v_day group by log.user_id),ranked as(select *,rank()over(order by contribution desc)rank_position from totals)select to_jsonb(ranked)from ranked where user_id=v_uid));
end $function$

CREATE OR REPLACE FUNCTION public.grant_canonical_daily_ranking_reward(p_ranking_day_key date, p_ranking_type text, p_recipient_user_id uuid, p_ranked_entity_id uuid, p_rank_position integer, p_score bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_award_id uuid; v_reward record; v_granted integer:=0; v_master_count integer;
begin
  if p_ranking_type not in ('POWER','GUILD_POWER','PVP','RAID_PERSONAL')
     or p_rank_position not between 1 and 100 then
    raise exception 'invalid daily ranking award' using errcode='22023';
  end if;
  select count(*) into v_master_count
  from public.canonical_daily_ranking_reward_master master
  where master.version='2026-09-03' and master.is_production_enabled
    and master.ranking_type=p_ranking_type
    and p_rank_position between master.rank_min and master.rank_max;
  if v_master_count<>2 then
    raise exception 'daily ranking reward master must resolve exactly two items' using errcode='23514';
  end if;

  insert into public.ranking_daily_reward_awards(
    ranking_day_key,ranking_type,recipient_user_id,ranked_entity_id,rank_position,score
  ) values(p_ranking_day_key,p_ranking_type,p_recipient_user_id,p_ranked_entity_id,p_rank_position,p_score)
  on conflict(ranking_day_key,ranking_type,recipient_user_id) do nothing
  returning id into v_award_id;
  if v_award_id is null then return 0; end if;

  for v_reward in
    select master.item_id,master.quantity
    from public.canonical_daily_ranking_reward_master master
    where master.version='2026-09-03' and master.is_production_enabled
      and master.ranking_type=p_ranking_type
      and p_rank_position between master.rank_min and master.rank_max
    order by master.item_id
  loop
    insert into public.ranking_daily_reward_item_grants(award_id,item_id,quantity)
    values(v_award_id,v_reward.item_id,v_reward.quantity);
    insert into public.user_items(user_id,item_id,quantity)
    values(p_recipient_user_id,v_reward.item_id,v_reward.quantity)
    on conflict(user_id,item_id) do update set
      quantity=public.user_items.quantity+excluded.quantity,updated_at=clock_timestamp();
    v_granted:=v_granted+1;
  end loop;

  insert into public.ranking_reward_notifications(
    recipient_user_id,period_kind,period_key,awarded_at,acknowledged_at
  ) values(p_recipient_user_id,'DAILY',p_ranking_day_key::text,clock_timestamp(),null)
  on conflict(recipient_user_id,period_kind,period_key) do update set
    awarded_at=excluded.awarded_at,acknowledged_at=null;
  return v_granted;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_canonical_guild_daily_exp(p_user_id uuid, p_source text, p_source_reference_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_guild uuid;v_exp integer;v_day date:=public.guild_jst_date();v_result jsonb;
begin
 select guild_id into v_guild from public.guild_members where user_id=p_user_id;
 if v_guild is null then return jsonb_build_object('status','not_in_guild'); end if;
 select exp_grant into v_exp from public.canonical_guild_exp_source_master where source=p_source and enabled and daily_per_member=1;
 if not found then raise exception 'unsupported Guild EXP source'; end if;
 insert into public.guild_exp_daily_ledger(guild_id,user_id,source,jst_date,exp_granted,source_reference_id)
 values(v_guild,p_user_id,p_source,v_day,v_exp,p_source_reference_id) on conflict(guild_id,user_id,source,jst_date) do nothing;
 if not found then return jsonb_build_object('status','already_recorded','source',p_source); end if;
 v_result:=public.apply_canonical_guild_exp(v_guild,v_exp);
 return jsonb_build_object('status','granted','source',p_source,'expGained',v_exp,'guild',v_result);
end $function$

CREATE OR REPLACE FUNCTION public.grant_canonical_raid_day_clear_reward(p_instance_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_instance public.raid_bosses%rowtype; v_claim public.raid_clear_reward_claims%rowtype; v_item record; v_inserted boolean; v_row_count integer;
begin
 select * into v_instance from public.raid_bosses where id=p_instance_id for update;
 if not found or v_instance.status<>'CLEARED' or v_instance.raid_day_key is null then return jsonb_build_object('eligible',false); end if;
 if not exists(select 1 from public.raid_instance_user_progress where raid_boss_instance_id=p_instance_id and user_id=p_user_id and finalized_battles>0) then return jsonb_build_object('eligible',false); end if;
 insert into public.raid_clear_reward_claims(raid_day_key,user_id,reward_type,source_instance_id)
 values(v_instance.raid_day_key,p_user_id,'CLEAR_REWARD',p_instance_id)
 on conflict do nothing; get diagnostics v_row_count=row_count; v_inserted:=v_row_count=1;
 select * into v_claim from public.raid_clear_reward_claims where raid_day_key=v_instance.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD' for update;
 if v_inserted then
  update public.raid_clear_reward_claims set ticket_roll=random()<0.30,ticket_item_id=public.resolve_canonical_reward_item('NORMAL_GACHA_TICKET_RANDOM'),awakening_roll=random()<0.01
  where raid_day_key=v_instance.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD' returning * into v_claim;
 end if;
 if not v_inserted and v_claim.delivery_status='DELIVERED' then return jsonb_build_object('eligible',true,'already_claimed',true); end if;
 begin
  for v_item in select * from (values('SKILL_MANUAL'::text,1,true),(v_claim.ticket_item_id,1,v_claim.ticket_roll),('AWAKENING_BOOK',1,v_claim.awakening_roll)) x(item_id,quantity,selected) where selected loop
   insert into public.raid_clear_reward_deliveries values(v_claim.raid_day_key,p_user_id,'CLEAR_REWARD',v_item.item_id,v_item.quantity,v_claim.source_instance_id,now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(p_user_id,v_item.item_id,v_item.quantity,'レイドクリア報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end loop;
  update public.raid_clear_reward_claims set delivery_status='DELIVERED',delivered_at=now(),last_error=null where raid_day_key=v_claim.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD';
 exception when others then
  update public.raid_clear_reward_claims set delivery_status='PENDING',last_error=sqlstate where raid_day_key=v_claim.raid_day_key and user_id=p_user_id and reward_type='CLEAR_REWARD';
 end;
 return jsonb_build_object('eligible',true,'already_claimed',not v_inserted,'ticket_roll',v_claim.ticket_roll,'awakening_roll',v_claim.awakening_roll);
end $function$

CREATE OR REPLACE FUNCTION public.grant_canonical_ranking_season_reward(p_season_id uuid, p_category text, p_recipient_user_id uuid, p_ranked_entity_id uuid, p_rank_position integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entry record;
  v_reward_id text;
  v_item_id text;
  v_quantity integer;
  v_reward_key text;
  v_granted integer := 0;
  v_message text;
  v_present_id uuid;
begin
  if p_category not in ('PVP','RAID_PERSONAL','RAID_GUILD') then
    raise exception 'unsupported ranking reward category' using errcode='22023';
  end if;
  v_message := case p_category
    when 'PVP' then 'PvPシーズンランキング報酬'
    when 'RAID_PERSONAL' then 'レイド個人ランキング報酬'
    else 'レイドギルドランキング報酬'
  end;

  for v_entry in
    select entry.value,entry.ordinality
    from jsonb_array_elements(public.canonical_ranking_reward_payload()#>array['progression',p_category])
      with ordinality entry(value,ordinality)
    where p_rank_position between (entry.value->>0)::integer and (entry.value->>1)::integer
  loop
    v_reward_id := v_entry.value->>2;
    v_quantity := (v_entry.value->>3)::integer;
    v_reward_key := concat_ws(':',v_entry.value->>0,v_entry.value->>1,v_reward_id,v_entry.ordinality);
    v_item_id := public.resolve_canonical_reward_item(v_reward_id);

    insert into public.ranking_season_reward_grants(
      season_id,ranking_category,recipient_user_id,ranked_entity_id,rank_position,
      reward_key,master_reward_id,resolved_item_id,quantity
    ) values (
      p_season_id,p_category,p_recipient_user_id,p_ranked_entity_id,p_rank_position,
      v_reward_key,v_reward_id,v_item_id,v_quantity
    ) on conflict do nothing;

    if found then
      insert into public.presents(user_id,item_id,quantity,message,status,expire_at)
      values(p_recipient_user_id,v_item_id,v_quantity,v_message,'UNCLAIMED',clock_timestamp()+interval '30 days')
      returning id into v_present_id;
      update public.ranking_season_reward_grants set present_id=v_present_id
      where season_id=p_season_id and ranking_category=p_category
        and recipient_user_id=p_recipient_user_id and reward_key=v_reward_key;
      v_granted := v_granted + 1;
    end if;
  end loop;
  return v_granted;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_mission_reward_bundle(p_delivery_ledger_id uuid, p_user_id uuid, p_mission_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_component record;
  v_mission public.missions%rowtype;
  v_item_id text;
  v_rewards jsonb := '[]'::jsonb;
  v_has_components boolean;
  v_order smallint := 0;
begin
  select * into strict v_mission from public.missions where id = p_mission_id;
  select exists(select 1 from public.mission_reward_components where mission_id=p_mission_id)
    into v_has_components;

  if v_has_components then
    for v_component in
      select reward_order,item_id,quantity from public.mission_reward_components
      where mission_id=p_mission_id order by reward_order
    loop
      v_item_id := public.resolve_canonical_reward_item(v_component.item_id);
      insert into public.mission_reward_delivery_items(delivery_ledger_id,reward_order,item_id,quantity)
      values(p_delivery_ledger_id,v_component.reward_order,v_item_id,v_component.quantity);
      perform public.grant_present_payload(p_user_id,v_item_id,v_component.quantity);
      v_rewards := v_rewards || jsonb_build_array(jsonb_build_object(
        'item_id',v_item_id,'quantity',v_component.quantity
      ));
      v_order := greatest(v_order,v_component.reward_order);
    end loop;
  else
    -- The caller resolves legacy random rewards once into the delivery ledger.
    -- Reuse that value so the audit row and actual direct grant cannot diverge.
    select resolved_item_id into v_item_id
    from public.mission_reward_delivery_ledger where id=p_delivery_ledger_id;
    if coalesce(v_item_id,'')<>'' and coalesce(v_mission.reward_quantity,0)>0 then
      v_order := 1;
      insert into public.mission_reward_delivery_items(delivery_ledger_id,reward_order,item_id,quantity)
      values(p_delivery_ledger_id,v_order,v_item_id,v_mission.reward_quantity);
      perform public.grant_present_payload(p_user_id,v_item_id,v_mission.reward_quantity);
      v_rewards := v_rewards || jsonb_build_array(jsonb_build_object(
        'item_id',v_item_id,'quantity',v_mission.reward_quantity
      ));
    end if;
  end if;

  if coalesce(v_mission.cash_reward,0)>0 then
    v_order := v_order + 1;
    insert into public.mission_reward_delivery_items(delivery_ledger_id,reward_order,item_id,quantity)
    values(p_delivery_ledger_id,v_order,'CASH',v_mission.cash_reward);
    perform public.grant_present_payload(p_user_id,'CASH',v_mission.cash_reward);
    v_rewards := v_rewards || jsonb_build_array(jsonb_build_object(
      'item_id','CASH','quantity',v_mission.cash_reward
    ));
  end if;
  return v_rewards;
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_present_payload(p_user_id uuid, p_item_id text, p_quantity integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_quantity <= 0 THEN RAISE EXCEPTION 'Invalid present quantity'; END IF;

  IF p_item_id = 'CASH' THEN
    UPDATE public.users SET cash = cash + p_quantity WHERE id = p_user_id;
  ELSIF p_item_id IN ('DIA', 'DIAMOND') THEN
    UPDATE public.users SET neon_diamonds = neon_diamonds + p_quantity WHERE id = p_user_id;
  ELSIF EXISTS (
    SELECT 1 FROM public.equipment_battle_master WHERE equipment_id = p_item_id
  ) THEN
    INSERT INTO public.user_equipments (
      user_id, equipment_id, equipment_master_id, level, plus_val
    )
    SELECT p_user_id, p_item_id, p_item_id, 1, 0
    FROM generate_series(1, p_quantity);
  ELSE
    INSERT INTO public.user_items (user_id, item_id, quantity)
    VALUES (p_user_id, p_item_id, p_quantity)
    ON CONFLICT (user_id, item_id) DO UPDATE
    SET quantity = public.user_items.quantity + EXCLUDED.quantity;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_raid_completion_xp(p_boss_id text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_boss public.raid_bosses%ROWTYPE;
  v_participant RECORD;
  v_reward_xp INTEGER;
  v_granted INTEGER := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.raid_damage_logs
    WHERE boss_id = p_boss_id AND user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Raid participation is required';
  END IF;

  SELECT * INTO v_boss
  FROM public.raid_bosses
  WHERE boss_id = p_boss_id AND status = 'DEFEATED'
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Raid boss is not defeated';
  END IF;

  FOR v_participant IN
    SELECT user_id, SUM(damage)::BIGINT AS total_damage
    FROM public.raid_damage_logs
    WHERE boss_id = p_boss_id
    GROUP BY user_id
  LOOP
    SELECT COALESCE(MAX(reward_xp), 0) INTO v_reward_xp
    FROM public.raid_rewards_master
    WHERE reward_type = 'DEFEAT_XP'
      AND threshold_val <= v_participant.total_damage;

    IF v_reward_xp > 0 THEN
      INSERT INTO public.raid_completion_xp_grants (raid_cycle_id, user_id, reward_xp)
      VALUES (v_boss.cycle_id, v_participant.user_id, v_reward_xp)
      ON CONFLICT DO NOTHING;
      IF FOUND THEN
        PERFORM public.apply_user_xp(v_participant.user_id, v_reward_xp);
        v_granted := v_granted + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN v_granted;
END;
$function$

CREATE OR REPLACE FUNCTION public.grant_raid_reward(p_instance_id uuid, p_user_id uuid, p_reward_id integer, p_reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_reward record;
begin
  insert into public.raid_reward_grants(raid_boss_instance_id,user_id,reward_id,reward_reason)
  values(p_instance_id,p_user_id,p_reward_id,p_reason) on conflict do nothing;
  if not found then return false; end if;
  select coalesce(reward_item_id,item_id) item_id, greatest(coalesce(reward_quantity,quantity,1),1) quantity
  into v_reward from public.raid_rewards_master where id=p_reward_id;
  insert into public.presents(user_id,item_id,quantity,message,status,expire_at)
  values(p_user_id,v_reward.item_id,v_reward.quantity,'レイド報酬','UNCLAIMED',now()+interval '30 days');
  return true;
end; $function$

CREATE OR REPLACE FUNCTION public.guard_daily_profile_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_today DATE := (now() AT TIME ZONE 'Asia/Tokyo')::DATE;
BEGIN
  IF NEW.username IS DISTINCT FROM OLD.username THEN
    IF char_length(btrim(NEW.username)) = 0 OR char_length(NEW.username) > 8 THEN
      RAISE EXCEPTION 'Username must be between 1 and 8 characters';
    END IF;
    IF OLD.last_username_changed_on = v_today THEN RAISE EXCEPTION 'Username can only be changed once per day'; END IF;
    NEW.last_username_changed_on := v_today;
  END IF;
  IF NEW.bio IS DISTINCT FROM OLD.bio THEN
    IF char_length(COALESCE(NEW.bio, '')) > 200 THEN RAISE EXCEPTION 'Bio must be 200 characters or fewer'; END IF;
    IF OLD.last_bio_changed_on = v_today THEN RAISE EXCEPTION 'Bio can only be changed once per day'; END IF;
    NEW.last_bio_changed_on := v_today;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_equipped_title_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.title_equipped IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_titles AS owned
    WHERE owned.user_id = NEW.id
      AND owned.title_id = NEW.title_equipped
  ) THEN
    RAISE EXCEPTION 'Equipped title must be owned by the user';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_gvg_defense_deck_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user_id UUID;
BEGIN
  v_user_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.user_id ELSE NEW.user_id END;
  IF EXISTS (
    SELECT 1
    FROM public.guild_members member
    JOIN public.gvg_match_sessions match ON match.guild_a_id = member.guild_id OR match.guild_b_id = member.guild_id
    WHERE member.user_id = v_user_id
      AND match.status = 'ACTIVE'
      AND now() >= match.scheduled_start_at AND now() < match.scheduled_end_at
  ) THEN
    RAISE EXCEPTION 'GvG defense decks are locked during active GvG';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_gvg_membership_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_guild_ids UUID[];
BEGIN
  v_guild_ids := ARRAY_REMOVE(ARRAY[
    CASE WHEN TG_OP <> 'INSERT' THEN OLD.guild_id ELSE NULL END,
    CASE WHEN TG_OP <> 'DELETE' THEN NEW.guild_id ELSE NULL END
  ], NULL);
  IF EXISTS (
    SELECT 1 FROM public.gvg_match_sessions match
    WHERE match.status = 'ACTIVE'
      AND now() >= match.scheduled_start_at AND now() < match.scheduled_end_at
      AND (match.guild_a_id = ANY(v_guild_ids) OR match.guild_b_id = ANY(v_guild_ids))
  ) THEN
    RAISE EXCEPTION 'Guild membership and roles are locked during active GvG';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_preopen_guild_power_cutoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_season_id uuid;
  v_starts_at timestamptz;
  v_ends_at timestamptz;
  v_status text;
  v_finalized boolean;
begin
  select season.id,season.starts_at,season.ends_at,season.status,
    exists(select 1 from public.ranking_guild_power_finalization_audits audit
           where audit.season_id=season.id)
  into strict v_season_id,v_starts_at,v_ends_at,v_status,v_finalized
  from public.ranking_guild_power_season_master master
  join public.ranking_seasons season on season.id=master.season_id
  where master.event_key='PREOPEN_GUILD_POWER_2026';

  if clock_timestamp()<v_starts_at then
    return null;
  end if;
  if v_status='PREPARING' then
    perform public.activate_preopen_guild_power_season();
  end if;
  if v_finalized then
    return null;
  elsif clock_timestamp()>=v_ends_at then
    perform public.finalize_preopen_guild_power_season();
  else
    -- Pre-cutoff work is admitted by season-row/share then advisory/share.
    -- The finalizer uses the same order with exclusive modes and waits for it.
    perform 1 from public.ranking_seasons where id=v_season_id for share;
    -- A transaction admitted before cutoff holds a shared lock through commit.
    -- The finalizer's exclusive lock therefore waits for all admitted writes.
    perform pg_advisory_xact_lock_shared(hashtextextended('PREOPEN_GUILD_POWER_2026',0));
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.gvg_season_reset()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', '') <> 'admin' THEN RAISE EXCEPTION 'admin role required'; END IF;
  DELETE FROM public.user_gvg_ranks;
  UPDATE public.guild_base_controls SET daily_points = 0, total_seasonal_days = 0, is_controlling = false, updated_at = now();
  INSERT INTO public.gvg_season_status (id, current_day, updated_at) VALUES (1, 1, now())
  ON CONFLICT (id) DO UPDATE SET current_day = 1, updated_at = EXCLUDED.updated_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.initialize_current_player(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid:=auth.uid();
  v_username text:=btrim(p_username);
  v_is_anonymous boolean:=coalesce((auth.jwt()->>'is_anonymous')::boolean,false);
begin
  if v_user_id is null then raise exception 'Authentication is required'; end if;
  if not v_is_anonymous then raise exception 'Anonymous onboarding session is required'; end if;
  if v_username is null or char_length(v_username) not between 1 and 8 then
    raise exception 'Username must contain 1 to 8 characters';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_user_id::text,0));
  if exists(select 1 from public.users where id=v_user_id) then
    insert into public.tutorial_progress(user_id,step_id) values(v_user_id,'WORLD_INTRO') on conflict(user_id) do nothing;
    return jsonb_build_object('status','already_initialized','tutorial_step',(select step_id from public.tutorial_progress where user_id=v_user_id));
  end if;
  if exists(select 1 from public.users where lower(btrim(username))=lower(v_username)) then
    raise exception 'Username is already in use' using errcode='23505';
  end if;
  insert into public.users(id,username,current_base_id,favorite_character_id)
  values(v_user_id,v_username,'shinjuku',null);
  insert into public.tutorial_progress(user_id,step_id) values(v_user_id,'WORLD_INTRO') on conflict(user_id) do nothing;
  return jsonb_build_object('status','success','tutorial_step','WORLD_INTRO');
end;
$function$

CREATE OR REPLACE FUNCTION public.initialize_current_player(p_username text, p_invite_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_result jsonb; v_invitation jsonb;
begin
 v_result:=public.initialize_current_player(p_username);
 if v_result->>'status'='success' and nullif(btrim(coalesce(p_invite_code,'')),'') is not null then
  v_invitation:=public.apply_current_player_invitation(p_invite_code);
  v_result:=v_result||jsonb_build_object('invitation',v_invitation);
 end if;
 return v_result;
end $function$

CREATE OR REPLACE FUNCTION public.initialize_new_user(p_user_id uuid, p_username text, p_character_id text, p_area_id text, p_gift_code text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_hair_id text DEFAULT NULL::text, p_face_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF char_length(trim(p_username)) NOT BETWEEN 1 AND 8 THEN
    RAISE EXCEPTION 'Username must contain 1 to 8 characters';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users WHERE username = trim(p_username) AND id <> p_user_id) THEN
    RAISE EXCEPTION 'Username is already in use';
  END IF;

  INSERT INTO public.users (
    id, username, current_base_id, favorite_character_id, gift_code
  ) VALUES (
    p_user_id, trim(p_username), COALESCE(NULLIF(p_area_id, ''), 'neon_tower'),
    COALESCE(NULLIF(p_character_id, ''), '11111111-1111-1111-1111-111111111111'),
    NULLIF(trim(COALESCE(p_gift_code, '')), '')
  ) ON CONFLICT (id) DO NOTHING;

  INSERT INTO public.user_characters (user_id, character_id, level, awakening_level)
  VALUES (
    p_user_id,
    COALESCE(NULLIF(p_character_id, ''), '11111111-1111-1111-1111-111111111111'),
    1,
    0
  ) ON CONFLICT (user_id, character_id) DO NOTHING;

  RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.issue_kpi_mypage_ready_context_v1(p_tutorial_version text, p_idempotency_key text, p_source text DEFAULT 'mypage_handshake_v1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_subject uuid := public.kpi_v249_current_subject(); v_user uuid := auth.uid();
  v_context public.kpi_tutorial_mypage_ready_contexts%rowtype; v_leader text;
  v_step text; v_completed timestamptz; v_guild uuid; v_profile_guild uuid; v_member_count int;
begin
  if p_tutorial_version is null or p_tutorial_version !~ '^[A-Za-z0-9_.-]{1,64}$'
     or p_idempotency_key is null or p_idempotency_key !~ '^[A-Za-z0-9_.:-]{1,128}$'
     or p_source not in ('mypage_handshake_v1','qa_v1') then
    raise exception 'Invalid My Page context request' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('kpi249:mypage:'||v_subject||':'||p_idempotency_key,0));
  select * into v_context from public.kpi_tutorial_mypage_ready_contexts
    where subject_id=v_subject and idempotency_key=p_idempotency_key;
  if found then
    if v_context.tutorial_version is distinct from p_tutorial_version or v_context.source is distinct from p_source then
      raise exception 'Conflicting My Page context retry' using errcode='23505'; end if;
    return jsonb_build_object('context_id',v_context.context_id,'expires_at',v_context.expires_at,
      'profile_ready',v_context.profile_ready,'onboarding_ready',v_context.onboarding_ready,
      'identity_leader_ready',v_context.identity_leader_ready,
      'guild_membership_resolved',v_context.guild_membership_resolved,
      'guild_membership_status',v_context.guild_membership_status);
  end if;
  select favorite_character_id,guild_id into v_leader,v_profile_guild from public.users
    where id=v_user and nullif(btrim(username),'') is not null;
  if not found then raise exception 'Profile is not ready' using errcode='23514'; end if;
  select step_id,completed_at into v_step,v_completed from public.tutorial_progress where user_id=v_user;
  if v_step not in ('COMPLETE','AUTHENTICATION') or v_completed is null then
    raise exception 'Onboarding is not ready' using errcode='23514'; end if;
  if v_leader is null or not exists(select 1 from public.user_characters where user_id=v_user and character_id=v_leader) then
    raise exception 'Identity leader is not ready' using errcode='23514'; end if;
  select count(*),(array_agg(guild_id))[1] into v_member_count,v_guild from public.guild_members where user_id=v_user;
  if v_member_count > 1 or (v_member_count=1 and (v_profile_guild is distinct from v_guild
       or not exists(select 1 from public.guilds where id=v_guild and not is_disbanded)))
     or (v_member_count=0 and v_profile_guild is not null) then
    raise exception 'Guild membership is inconsistent' using errcode='23514'; end if;
  insert into public.kpi_tutorial_mypage_ready_contexts(subject_id,expires_at,profile_ready,onboarding_ready,
    identity_leader_ready,guild_membership_resolved,guild_membership_status,tutorial_version,source,idempotency_key)
  values(v_subject,clock_timestamp()+interval '10 minutes',true,true,true,true,
    case when v_member_count=1 then 'MEMBER' else 'NOT_MEMBER' end,p_tutorial_version,p_source,p_idempotency_key)
  returning * into v_context;
  return jsonb_build_object('context_id',v_context.context_id,'expires_at',v_context.expires_at,
    'profile_ready',true,'onboarding_ready',true,'identity_leader_ready',true,
    'guild_membership_resolved',true,'guild_membership_status',v_context.guild_membership_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.join_guild(p_guild_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_mode text;
  v_cap integer;
  v_count integer;
  v_user public.users%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication is required'; end if;
  select * into v_user from public.users where id = auth.uid() for update;
  if not found then raise exception 'Guild joining requirements are not met'; end if;
  if v_user.last_guild_left_at is not null and v_user.last_guild_left_at > now() - interval '24 hours' then
    raise exception 'Guild rejoin cooldown is active'
      using errcode = 'P0001', detail = 'GUILD_JOIN_COOLDOWN_ACTIVE';
  end if;
  if exists(select 1 from public.guild_members where user_id = auth.uid()) then raise exception 'Already in a guild'; end if;
  select recruitment_mode, public.canonical_guild_member_cap(id)
    into v_mode, v_cap
  from public.guilds
  where id = p_guild_id and not is_disbanded
  for update;
  if not found then raise exception 'Guild not found'; end if;
  if v_mode <> 'OPEN_JOIN' then raise exception 'Guild does not accept direct joins'; end if;
  select count(*) into v_count from public.guild_members where guild_id = p_guild_id;
  if v_count >= v_cap then raise exception 'Guild member cap reached'; end if;
  insert into public.guild_members(guild_id, user_id, role, weekly_contribution, total_contribution)
  values(p_guild_id, auth.uid(), 'MEMBER', 0, 0);
  update public.guild_join_requests
  set status = 'CANCELLED', reviewed_at = now(), reviewed_by = auth.uid()
  where user_id = auth.uid() and status = 'PENDING';
  perform public.evaluate_mission_progress(auth.uid(), 'GUILD_JOIN', 1);
  return jsonb_build_object('status', 'success');
end;
$function$

CREATE OR REPLACE FUNCTION public.kick_guild_member(p_guild_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_actor_role text; v_target_role text;
BEGIN
  IF auth.uid() IS NULL OR p_user_id = auth.uid() THEN RAISE EXCEPTION 'Invalid guild member removal'; END IF;
  SELECT role INTO v_actor_role FROM public.guild_members WHERE guild_id = p_guild_id AND user_id = auth.uid();
  SELECT role INTO v_target_role FROM public.guild_members WHERE guild_id = p_guild_id AND user_id = p_user_id;
  IF NOT COALESCE(
    (v_actor_role = 'MASTER' AND v_target_role IN ('SUB_MASTER', 'MEMBER'))
    OR (v_actor_role = 'SUB_MASTER' AND v_target_role = 'MEMBER'), false
  ) THEN RAISE EXCEPTION 'Insufficient guild member removal permission'; END IF;
  DELETE FROM public.guild_members WHERE guild_id = p_guild_id AND user_id = p_user_id;
  UPDATE public.users SET last_guild_left_at = now() WHERE id = p_user_id;
  RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.kpi_ensure_subject(p_user_id uuid, p_registered_at timestamp with time zone DEFAULT now(), p_registration_type text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
declare
  v_subject_id uuid;
  v_registration_type text := p_registration_type;
begin
  if p_user_id is null then
    raise exception 'p_user_id is required' using errcode = '22004';
  end if;


  select subject_id into v_subject_id
  from public.kpi_subjects
  where source_user_id = p_user_id;
  if v_subject_id is not null then
    return v_subject_id;
  end if;


  if v_registration_type is null then
    select case when au.is_anonymous then 'anonymous' else 'authenticated' end
    into v_registration_type
    from auth.users au
    where au.id = p_user_id;
  end if;
  v_registration_type := coalesce(v_registration_type, 'unknown');


  begin
    insert into public.kpi_subjects(source_user_id, registered_at, registration_type)
    values(p_user_id, coalesce(p_registered_at, now()), v_registration_type)
    returning subject_id into v_subject_id;
  exception when unique_violation then
    select subject_id into v_subject_id
    from public.kpi_subjects
    where source_user_id = p_user_id;
  end;


  return v_subject_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_guard_acquisition_first_touch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_table_name='kpi_acquisition_subject_bindings' then
    if old.first_touch_source is not null and (tg_op='DELETE' or to_jsonb(new) is distinct from to_jsonb(old)) then
      raise exception 'Canonical First Touch is immutable' using errcode='23514';
    end if;
    if tg_op='UPDATE' and (new.journey_id is distinct from old.journey_id or new.subject_id is distinct from old.subject_id) then
      raise exception 'Acquisition binding identity is immutable' using errcode='23514';
    end if;
  elsif tg_op='UPDATE' then
    if (to_jsonb(new)-'metadata'-'first_arrived_at') is distinct from (to_jsonb(old)-'metadata'-'first_arrived_at')
      or (old.metadata<>'{}'::jsonb and new.metadata is distinct from old.metadata) then
      raise exception 'Acquisition Journey is immutable' using errcode='23514';
    end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_record_daily_activity(p_user_id uuid, p_occurred_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_subject_id uuid;
  v_activity_date date;
begin
  v_subject_id := public.kpi_ensure_subject(p_user_id, p_occurred_at, null);
  v_activity_date := (p_occurred_at at time zone 'Asia/Tokyo')::date;


  insert into public.kpi_daily_user_activity(
    activity_date, subject_id, first_active_at, last_active_at, source
  ) values (
    v_activity_date, v_subject_id, p_occurred_at, p_occurred_at, 'sync_active_users'
  )
  on conflict (activity_date, subject_id) do update
  set first_active_at = least(public.kpi_daily_user_activity.first_active_at, excluded.first_active_at),
      last_active_at = greatest(public.kpi_daily_user_activity.last_active_at, excluded.last_active_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.kpi_v249_current_subject()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_subject uuid; v_user uuid := auth.uid(); v_session uuid;
begin
  if v_user is null or auth.jwt()->>'role' is distinct from 'authenticated' then
    raise exception 'Valid authenticated session required' using errcode = '42501';
  end if;
  begin v_session := (auth.jwt()->>'session_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'Invalid session context' using errcode = '42501';
  end;
  if v_session is null or not exists (
    select 1 from auth.sessions where id = v_session and user_id = v_user
      and (not_after is null or not_after > clock_timestamp())
  ) then raise exception 'Session is not active' using errcode = '42501'; end if;
  select subject_id into v_subject from public.kpi_subjects
  where source_user_id = v_user and detached_at is null;
  if v_subject is null then
    raise exception 'Game Start subject does not exist' using errcode = '42501';
  end if;
  return v_subject;
end;
$function$

CREATE OR REPLACE FUNCTION public.leave_guild(p_user_id uuid, p_guild_id uuid, p_is_master boolean, p_has_others boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;v_other integer;
begin if auth.uid() is null or auth.uid()<>p_user_id then raise exception 'Only current user can leave Guild'; end if;
 perform 1 from public.guilds where id=p_guild_id for update; select role into v_role from public.guild_members where guild_id=p_guild_id and user_id=auth.uid() for update;
 if v_role is null then raise exception 'Guild membership required'; end if; select count(*) into v_other from public.guild_members where guild_id=p_guild_id and user_id<>auth.uid();
 if v_role='MASTER' and v_other>0 then raise exception 'Transfer MASTER before leaving Guild'; end if;
 delete from public.guild_members where guild_id=p_guild_id and user_id=auth.uid(); update public.users set last_guild_left_at=now() where id=auth.uid();
 if v_role='MASTER' then update public.guilds set is_disbanded=true,disbanded_at=now(),recruitment_mode='CLOSED',approval_required=false where id=p_guild_id; end if;
 return jsonb_build_object('status','success','disbanded',v_role='MASTER'); end $function$

CREATE OR REPLACE FUNCTION public.level_up_character(p_character_id uuid, p_exp_item_id text, p_count integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_level integer; v_awakening integer; v_new_level integer; v_gain integer;
  v_level_cap integer; v_cost bigint; v_material_cost integer; v_cash bigint; v_quantity integer;
begin
  if v_user_id is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if p_exp_item_id not in ('CHAR_EXP_S','CHAR_EXP_M','CHAR_EXP_L') or p_count < 1 or p_count > 100 then
    raise exception 'invalid character training request' using errcode = '22023';
  end if;
  select coalesce(level, 1), coalesce(awakening_level, 0) into v_level, v_awakening from public.user_characters
  where id = p_character_id and user_id = v_user_id for update;
  if not found then raise exception 'owned character not found' using errcode = 'P0002'; end if;
  v_level_cap := least(100, 50 + least(greatest(v_awakening, 0), 5) * 10);
  v_new_level := least(v_level + p_count, v_level_cap);
  v_gain := v_new_level - v_level;
  if v_gain <= 0 then raise exception 'character level cap reached' using errcode = '23514'; end if;
  select sum(cost_cash), sum(required_material_count) into v_cost, v_material_cost
  from public.character_level_up_master where level between v_level + 1 and v_new_level;
  if v_cost is null or v_material_cost is null then raise exception 'character level master is incomplete' using errcode = 'P0002'; end if;
  select cash into v_cash from public.users where id = v_user_id for update;
  select quantity into v_quantity from public.user_items where user_id = v_user_id and item_id = p_exp_item_id for update;
  if coalesce(v_cash,0) < v_cost then raise exception 'insufficient cash' using errcode = '23514'; end if;
  if coalesce(v_quantity,0) < v_material_cost then raise exception 'insufficient character training material' using errcode = '23514'; end if;
  update public.users set cash = cash - v_cost where id = v_user_id;
  update public.user_items set quantity = quantity - v_material_cost where user_id = v_user_id and item_id = p_exp_item_id;
  update public.user_characters set level = v_new_level where id = p_character_id and user_id = v_user_id;
  perform public.evaluate_mission_progress(v_user_id, 'CHAR_LEVEL_UP', v_gain);
  return jsonb_build_object('status','success','level',v_new_level,'levels_gained',v_gain,'cash_spent',v_cost,'remaining_cash',v_cash-v_cost);
end; $function$

CREATE OR REPLACE FUNCTION public.level_up_equipment(p_equipment_id uuid, p_exp_item_id text, p_count integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_level integer; v_plus integer; v_new_level integer; v_gain integer; v_level_cap integer;
  v_cost bigint; v_material_cost integer; v_cash bigint; v_quantity integer;
begin
  if v_user_id is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_exp_item_id not in ('EQUIP_EXP_S','EQUIP_EXP_M','EQUIP_EXP_L') or p_count < 1 or p_count > 100 then
    raise exception 'invalid equipment training request' using errcode='22023';
  end if;
  select coalesce(level,1),coalesce(plus_val,0) into v_level,v_plus
  from public.user_equipments where id=p_equipment_id and user_id=v_user_id for update;
  if not found then raise exception 'owned equipment not found' using errcode='P0002'; end if;
  v_level_cap := public.canonical_equipment_level_cap(v_plus);
  v_new_level := least(v_level+p_count,v_level_cap); v_gain := v_new_level-v_level;
  if v_gain <= 0 then raise exception 'equipment level cap reached' using errcode='23514'; end if;
  select sum(cost_cash),sum(required_exp) into v_cost,v_material_cost
  from public.equipment_level_up_master where level between v_level+1 and v_new_level;
  if v_cost is null or v_material_cost is null then raise exception 'equipment level master is incomplete' using errcode='P0002'; end if;
  select cash into v_cash from public.users where id=v_user_id for update;
  select quantity into v_quantity from public.user_items where user_id=v_user_id and item_id=p_exp_item_id for update;
  if coalesce(v_cash,0)<v_cost then raise exception 'insufficient cash' using errcode='23514'; end if;
  if coalesce(v_quantity,0)<v_material_cost then raise exception 'insufficient equipment training material' using errcode='23514'; end if;
  update public.users set cash=cash-v_cost where id=v_user_id;
  update public.user_items set quantity=quantity-v_material_cost where user_id=v_user_id and item_id=p_exp_item_id;
  update public.user_equipments set level=v_new_level where id=p_equipment_id and user_id=v_user_id;
  perform public.evaluate_mission_progress(v_user_id,'GEAR_UPGRADE',v_gain);
  return jsonb_build_object('status','success','level',v_new_level,'levels_gained',v_gain,'level_cap',v_level_cap,'cash_spent',v_cost,'remaining_cash',v_cash-v_cost);
end $function$

CREATE OR REPLACE FUNCTION public.limit_break_equipment(p_equipment_id uuid, p_use_wildcard boolean, p_dupe_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_user_id uuid:=auth.uid(); v_master_id text; v_plus integer; v_next integer; v_required integer; v_dupe_master_id text; begin
 if v_user_id is null then raise exception 'authentication required' using errcode='42501'; end if;
 select coalesce(nullif(equipment_id,''),equipment_master_id),coalesce(plus_val,0) into v_master_id,v_plus from public.user_equipments where id=p_equipment_id and user_id=v_user_id for update;
 if not found then raise exception 'owned equipment not found' using errcode='P0002'; end if;
 if v_plus>=10 then raise exception 'equipment limit break cap reached' using errcode='23514'; end if;
 v_next:=v_plus+1; select equivalent_cost into v_required from public.canonical_equipment_lb_steps where version='2026-08-21' and plus_val=v_next;
 if p_use_wildcard then update public.user_items set quantity=quantity-v_required where user_id=v_user_id and item_id='EQUIP_LB_PART' and quantity>=v_required; if not found then raise exception 'insufficient equipment limit break material' using errcode='23514'; end if;
 else if p_dupe_id is null or p_dupe_id=p_equipment_id then raise exception 'valid duplicate equipment is required' using errcode='22023'; end if; select coalesce(nullif(equipment_id,''),equipment_master_id) into v_dupe_master_id from public.user_equipments where id=p_dupe_id and user_id=v_user_id and equipped_character_id is null for update; if not found or v_dupe_master_id is distinct from v_master_id then raise exception 'matching unequipped duplicate is required' using errcode='23514'; end if; delete from public.user_equipments where id=p_dupe_id and user_id=v_user_id; end if;
 update public.user_equipments set plus_val=v_next where id=p_equipment_id and user_id=v_user_id;
 perform public.evaluate_mission_progress(v_user_id,'GEAR_LIMIT_BREAK',1);
 return jsonb_build_object('status','success','plus_val',v_next,'equivalent_cost',v_required); end $function$

CREATE OR REPLACE FUNCTION public.limit_break_gear(p_user_id uuid, p_equipment_id uuid, p_cash_cost integer, p_hammer_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_cash INTEGER;
    v_item_qty INTEGER;
    v_equip_plus INTEGER;
BEGIN
    SELECT cash INTO v_cash FROM public.users WHERE id = p_user_id;
    IF v_cash IS NULL OR v_cash < p_cash_cost THEN
        RETURN jsonb_build_object('error', 'キャッシュが不足しています。');
    END IF;

    SELECT quantity INTO v_item_qty FROM public.user_items WHERE user_id = p_user_id AND item_id = 'EQUIP_LB_HAMMER';
    IF v_item_qty IS NULL OR v_item_qty < p_hammer_cost THEN
        RETURN jsonb_build_object('error', '限界突破ハンマーが不足しています。');
    END IF;

    SELECT plus_val INTO v_equip_plus FROM public.user_equipments WHERE id = p_equipment_id AND user_id = p_user_id;
    IF v_equip_plus IS NULL THEN
        RETURN jsonb_build_object('error', '装備が存在しません。');
    END IF;

    UPDATE public.users SET cash = cash - p_cash_cost WHERE id = p_user_id;
    UPDATE public.user_items SET quantity = quantity - p_hammer_cost WHERE user_id = p_user_id AND item_id = 'EQUIP_LB_HAMMER';
    UPDATE public.user_equipments SET plus_val = plus_val + 1 WHERE id = p_equipment_id AND user_id = p_user_id;

    PERFORM public.evaluate_mission_progress(p_user_id, 'GEAR_LIMIT_BREAK', 1);
    RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.limit_break_gear_v2(p_user_id uuid, p_equipment_id uuid, p_cash_cost integer, p_use_wildcard boolean, p_dupe_id uuid, p_new_options jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_cash INTEGER;
    v_item_qty INTEGER;
    v_equip_plus INTEGER;
    v_dupe_exists BOOLEAN;
BEGIN
    SELECT cash INTO v_cash FROM public.users WHERE id = p_user_id;
    IF v_cash IS NULL OR v_cash < p_cash_cost THEN
        RETURN jsonb_build_object('error', 'キャッシュが不足しています。');
    END IF;

    IF p_use_wildcard THEN
        SELECT quantity INTO v_item_qty FROM public.user_items WHERE user_id = p_user_id AND item_id = 'EQUIP_LB_HAMMER';
        IF v_item_qty IS NULL OR v_item_qty < 1 THEN
            RETURN jsonb_build_object('error', '代用素材「万能カスタムツール [装備]」が不足しています。');
        END IF;
    ELSE
        SELECT EXISTS(SELECT 1 FROM public.user_equipments WHERE id = p_dupe_id AND user_id = p_user_id AND equipped_character_id IS NULL) INTO v_dupe_exists;
        IF NOT v_dupe_exists THEN
            RETURN jsonb_build_object('error', '同名の予備装備品が見つかりません。');
        END IF;
    END IF;

    SELECT plus_val INTO v_equip_plus FROM public.user_equipments WHERE id = p_equipment_id AND user_id = p_user_id;
    IF v_equip_plus IS NULL THEN
        RETURN jsonb_build_object('error', '対象装備が存在しません。');
    END IF;

    UPDATE public.users SET cash = cash - p_cash_cost WHERE id = p_user_id;
    
    IF p_use_wildcard THEN
        UPDATE public.user_items SET quantity = quantity - 1 WHERE user_id = p_user_id AND item_id = 'EQUIP_LB_HAMMER';
    ELSE
        DELETE FROM public.user_equipments WHERE id = p_dupe_id;
    END IF;

    UPDATE public.user_equipments 
    SET plus_val = plus_val + 1, random_options = p_new_options 
    WHERE id = p_equipment_id AND user_id = p_user_id;

    PERFORM public.evaluate_mission_progress(p_user_id, 'GEAR_LIMIT_BREAK', 1);
    RETURN jsonb_build_object('status', 'success', 'next_plus', v_equip_plus + 1);
END;
$function$

CREATE OR REPLACE FUNCTION public.limit_break_skill(p_skill_id uuid, p_use_wildcard boolean, p_dupe_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid(); v_skill_card_id text; v_plus integer; v_next integer;
  v_cost bigint; v_required integer; v_cash bigint; v_quantity integer; v_dupe_skill_id text; v_material_id text;
begin
  if v_user_id is null then raise exception 'authentication required' using errcode = '42501'; end if;
  select skill_card_id, coalesce(plus_val, 0) into v_skill_card_id, v_plus from public.user_skills
  where id=p_skill_id and user_id=v_user_id for update;
  if not found then raise exception 'owned skill not found' using errcode = 'P0002'; end if;
  if v_plus >= 10 then raise exception 'skill limit break cap reached' using errcode = '23514'; end if;
  v_next := v_plus + 1;
  select cost_cash, required_book into v_cost, v_required from public.skill_limit_break_master where plus_val=v_next;
  if not found then raise exception 'skill limit break master is incomplete' using errcode = 'P0002'; end if;
  select cash into v_cash from public.users where id=v_user_id for update;
  if coalesce(v_cash,0) < v_cost then raise exception 'insufficient cash' using errcode = '23514'; end if;
  v_material_id := 'SKILL_MANUAL';
  if p_use_wildcard then
    select quantity into v_quantity from public.user_items where user_id=v_user_id and item_id=v_material_id for update;
    if coalesce(v_quantity,0) < v_required then raise exception 'insufficient skill limit break material' using errcode = '23514'; end if;
  else
    if p_dupe_id is null or p_dupe_id=p_skill_id then raise exception 'valid duplicate skill is required' using errcode = '22023'; end if;
    select skill_card_id into v_dupe_skill_id from public.user_skills where id=p_dupe_id and user_id=v_user_id and equipped_character_id is null for update;
    if not found or v_dupe_skill_id is distinct from v_skill_card_id then raise exception 'matching unequipped duplicate is required' using errcode = '23514'; end if;
  end if;
  update public.users set cash=cash-v_cost where id=v_user_id;
  if p_use_wildcard then update public.user_items set quantity=quantity-v_required where user_id=v_user_id and item_id=v_material_id;
  else delete from public.user_skills where id=p_dupe_id and user_id=v_user_id; end if;
  update public.user_skills set plus_val=v_next where id=p_skill_id and user_id=v_user_id;
  perform public.evaluate_mission_progress(v_user_id,'SKILL_LIMIT_BREAK',1);
  return jsonb_build_object('status','success','plus_val',v_next,'cash_spent',v_cost,'remaining_cash',v_cash-v_cost,'material_id',v_material_id);
end; $function$

CREATE OR REPLACE FUNCTION public.limit_break_skill(p_user_id uuid, p_skill_id uuid, p_cash_cost integer, p_book_cost integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_cash INTEGER;
    v_item_qty INTEGER;
    v_skill_plus INTEGER;
BEGIN
    SELECT cash INTO v_cash FROM public.users WHERE id = p_user_id;
    IF v_cash IS NULL OR v_cash < p_cash_cost THEN
        RETURN jsonb_build_object('error', 'キャッシュが不足しています。');
    END IF;

    SELECT quantity INTO v_item_qty FROM public.user_items WHERE user_id = p_user_id AND item_id = 'SKILL_LB_BOOK';
    IF v_item_qty IS NULL OR v_item_qty < p_book_cost THEN
        RETURN jsonb_build_object('error', '奥義書が不足しています。');
    END IF;

    SELECT plus_val INTO v_skill_plus FROM public.user_skills WHERE id = p_skill_id AND user_id = p_user_id;
    IF v_skill_plus IS NULL THEN
        RETURN jsonb_build_object('error', 'スキルが存在しません。');
    END IF;

    UPDATE public.users SET cash = cash - p_cash_cost WHERE id = p_user_id;
    UPDATE public.user_items SET quantity = quantity - p_book_cost WHERE user_id = p_user_id AND item_id = 'SKILL_LB_BOOK';
    UPDATE public.user_skills SET plus_val = plus_val + 1 WHERE id = p_skill_id AND user_id = p_user_id;

    PERFORM public.evaluate_mission_progress(p_user_id, 'SKILL_LIMIT_BREAK', 1);
    RETURN jsonb_build_object('status', 'success');
END;
$function$

CREATE OR REPLACE FUNCTION public.limit_break_skill_v2(p_user_id uuid, p_skill_id uuid, p_cash_cost integer, p_use_wildcard boolean, p_dupe_id uuid, p_wildcard_item_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_cash INTEGER;
    v_item_qty INTEGER;
    v_skill_plus INTEGER;
    v_dupe_exists BOOLEAN;
BEGIN
    SELECT cash INTO v_cash FROM public.users WHERE id = p_user_id;
    IF v_cash IS NULL OR v_cash < p_cash_cost THEN
        RETURN jsonb_build_object('error', 'キャッシュが不足しています。');
    END IF;

    IF p_use_wildcard THEN
        SELECT quantity INTO v_item_qty FROM public.user_items WHERE user_id = p_user_id AND item_id = p_wildcard_item_id;
        IF v_item_qty IS NULL OR v_item_qty < 1 THEN
            RETURN jsonb_build_object('error', '限界突破の書が不足しています。');
        END IF;
    ELSE
        SELECT EXISTS(SELECT 1 FROM public.user_skills WHERE id = p_dupe_id AND user_id = p_user_id AND equipped_character_id IS NULL) INTO v_dupe_exists;
        IF NOT v_dupe_exists THEN
            RETURN jsonb_build_object('error', '同名の予備スキルカードが見つかりません。');
        END IF;
    END IF;

    SELECT plus_val INTO v_skill_plus FROM public.user_skills WHERE id = p_skill_id AND user_id = p_user_id;
    IF v_skill_plus IS NULL THEN
        RETURN jsonb_build_object('error', '対象スキルが存在しません。');
    END IF;

    UPDATE public.users SET cash = cash - p_cash_cost WHERE id = p_user_id;
    
    IF p_use_wildcard THEN
        UPDATE public.user_items SET quantity = quantity - 1 WHERE user_id = p_user_id AND item_id = p_wildcard_item_id;
    ELSE
        DELETE FROM public.user_skills WHERE id = p_dupe_id;
    END IF;

    UPDATE public.user_skills SET plus_val = plus_val + 1 WHERE id = p_skill_id AND user_id = p_user_id;

    PERFORM public.evaluate_mission_progress(p_user_id, 'SKILL_LIMIT_BREAK', 1);
    RETURN jsonb_build_object('status', 'success', 'next_plus', v_skill_plus + 1);
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_chat_channel_read(p_target_type text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
BEGIN
  IF auth.uid() IS NULL OR p_target_type NOT IN ('GLOBAL', 'GUILD') THEN
    RAISE EXCEPTION 'Invalid chat channel';
  END IF;

  IF p_target_type = 'GUILD' THEN
    SELECT guild_id INTO v_target_id
    FROM public.guild_members
    WHERE user_id = auth.uid();

    IF v_target_id IS NULL THEN
      RAISE EXCEPTION 'Guild membership required';
    END IF;
  END IF;

  INSERT INTO public.chat_read_states (user_id, target_type, target_id, last_read_at)
  VALUES (auth.uid(), p_target_type, v_target_id, clock_timestamp())
  ON CONFLICT (user_id, target_type, target_id)
  DO UPDATE SET last_read_at = EXCLUDED.last_read_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_mission_event_dialog_viewed(p_event_id text, p_jst_date date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid:=auth.uid();
  v_today date:=(clock_timestamp() at time zone 'Asia/Tokyo')::date;
  v_inserted boolean;
begin
  if v_uid is null then raise exception 'authentication required' using errcode='42501'; end if;
  if p_jst_date is distinct from v_today or not exists(
    select 1 from public.mission_events event where event.id=p_event_id and event.is_enabled
      and clock_timestamp()>=event.start_at and clock_timestamp()<event.progress_end_at
  ) then raise exception 'event dialog is not currently presentable' using errcode='23514'; end if;
  insert into public.mission_event_dialog_views(user_id,event_id,jst_date)
  values(v_uid,p_event_id,p_jst_date) on conflict do nothing returning true into v_inserted;
  if coalesce(v_inserted,false) then
    insert into public.mission_event_telemetry(event_id,user_id,event_name,jst_date,source)
    values(p_event_id,v_uid,'dialog_presented',v_today,'login_dialog_queue');
  end if;
  return coalesce(v_inserted,false);
end;
$function$

CREATE OR REPLACE FUNCTION public.move_current_user_base(p_base_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_previous_base_id text;
begin
  if v_uid is null then
    raise exception 'Player authentication required' using errcode = '42501';
  end if;
  if p_base_id is null or p_base_id not in (
    'shinjuku', 'shibuya', 'ikebukuro', 'roppongi',
    'akihabara', 'kawasaki', 'yokohama'
  ) then
    raise exception 'Invalid base id' using errcode = '22023';
  end if;

  select current_base_id into v_previous_base_id
  from public.users
  where id = v_uid
  for update;
  if not found then
    raise exception 'Player was not found' using errcode = 'P0002';
  end if;

  update public.users
  set current_base_id = p_base_id
  where id = v_uid;

  return jsonb_build_object(
    'status', 'success',
    'previous_base_id', v_previous_base_id,
    'current_base_id', p_base_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.normalize_user_mission_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target integer;
BEGIN
  SELECT target_value INTO v_target
  FROM public.missions
  WHERE id = NEW.mission_id;

  IF v_target IS NULL THEN
    RAISE EXCEPTION 'Mission master not found';
  END IF;

  NEW.current_progress := LEAST(GREATEST(COALESCE(NEW.current_progress, 0), 0), v_target);
  NEW.progress_val := NEW.current_progress;
  IF NEW.status = 'PROGRESS' AND NEW.current_progress >= v_target THEN
    NEW.status := 'CLEAR';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.on_canonical_daily_activity_finalized()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_day date:=(new.finalized_at at time zone 'Asia/Tokyo')::date; v_count integer; v_consumed integer; v_key text;
begin
 if old.finalization_status='FINALIZED' or new.finalization_status<>'FINALIZED' then return new; end if;
 if new.battle_mode='PVP' then
  v_key:='PVP_BATTLE:'||new.id::text;
  insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,v_key,new.id,'[{"itemId":"CHAR_EXP_S","quantity":1}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'CHAR_EXP_S',1,'PvPバトル報酬','UNCLAIMED',now()+interval '30 days'); end if;
  select count(*) into v_count from public.battle_replay_sessions where requester_user_id=new.requester_user_id and battle_mode='PVP' and finalization_status='FINALIZED' and (finalized_at at time zone 'Asia/Tokyo')::date=v_day;
  if v_count>=3 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'PVP_DAILY_3',new.id,'[{"itemId":"SKILL_MANUAL","quantity":1},{"itemId":"CASH","quantity":40}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'SKILL_MANUAL',1,'PvPデイリー報酬','UNCLAIMED',now()+interval '30 days'),(new.requester_user_id,'CASH',40,'PvPデイリー報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
 elsif new.battle_mode='RAID' then
  v_key:='RAID_BATTLE:'||new.id::text;
  insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,v_key,new.id,'[{"itemId":"EQUIP_EXP_S","quantity":1}]',now()) on conflict do nothing;
  if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'EQUIP_EXP_S',1,'レイドバトル報酬','UNCLAIMED',now()+interval '30 days'); end if;
  select count(*) into v_count from public.battle_replay_sessions where requester_user_id=new.requester_user_id and battle_mode='RAID' and finalization_status='FINALIZED' and (finalized_at at time zone 'Asia/Tokyo')::date=v_day;
  if v_count>=3 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'RAID_DAILY_3',new.id,'[{"itemId":"CHAR_EXP_M","quantity":1},{"itemId":"CASH","quantity":40}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'CHAR_EXP_M',1,'レイドデイリー報酬','UNCLAIMED',now()+interval '30 days'),(new.requester_user_id,'CASH',40,'レイドデイリー報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
  select coalesce(sum(progress.raid_points_consumed),0) into v_consumed from public.raid_instance_user_progress progress join public.raid_bosses boss on boss.id=progress.raid_boss_instance_id where progress.user_id=new.requester_user_id and boss.raid_day_key=v_day::text;
  if v_consumed>=5 then
   insert into public.canonical_daily_activity_claims values(v_day,new.requester_user_id,'RAID_POINTS_5',new.id,'[{"itemId":"EQUIP_LB_PART","quantity":1}]',now()) on conflict do nothing;
   if found then insert into public.presents(user_id,item_id,quantity,message,status,expire_at) values(new.requester_user_id,'EQUIP_LB_PART',1,'レイド参加報酬','UNCLAIMED',now()+interval '30 days'); end if;
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.on_canonical_guild_quest_exp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_guild uuid;v_day date:=public.guild_jst_date();v_count integer;
begin
 if new.status not in('COMPLETED','CLAIMABLE','CLAIMED') or old.status in('COMPLETED','CLAIMABLE','CLAIMED') then return new; end if;
 select guild_id into v_guild from public.guild_members where user_id=new.user_id; if v_guild is null then return new; end if;
 insert into public.guild_exp_daily_progress(guild_id,user_id,source,jst_date,event_count) values(v_guild,new.user_id,'QUEST_3_CLEAR',v_day,1)
 on conflict(guild_id,user_id,source,jst_date) do update set event_count=public.guild_exp_daily_progress.event_count+1,updated_at=now() returning event_count into v_count;
 if v_count=3 then perform public.grant_canonical_guild_daily_exp(new.user_id,'QUEST_3_CLEAR',new.id); end if; return new;
end $function$

CREATE OR REPLACE FUNCTION public.on_daily_mission_authority_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_mission public.missions%rowtype;
begin
  -- Rollover resets CLEAR/CLAIMED rows to PROGRESS in one statement. Ignore
  -- those reverse transitions so this row trigger never updates another row
  -- that the same statement is still scheduled to update.
  if old.status is not distinct from new.status
    or new.status not in ('CLEAR', 'CLAIMED') then
    return new;
  end if;
  select * into v_mission from public.missions where id = new.mission_id;
  if not found
    or not v_mission.is_enabled
    or v_mission.category <> 'DAILY'
    or v_mission.trigger_type = 'DAILY_MISSION_COMPLETED_COUNT'
    or new.cycle_date is null then
    return new;
  end if;
  perform public.refresh_daily_mission_completion_aggregates(new.user_id, new.cycle_date);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.on_kpi_auth_method_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
