    occurred_at,source,idempotency_key)
  values(v_subject,new.guild_id,v_period,v_type,new.joined_at,'server_v1','guild-membership:'||new.id);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.on_m9x_gacha_activity()
